import '../models/learning_models.dart';

const List<GeoTopic> computerTopics = <GeoTopic>[
  GeoTopic(
    id: "fundamentals",
    title: "Computer Course: Computer ki Buniyad",
    subtitle: "Computer kya hota hai, us ke hisse, memory aur internet ki pehli samajh",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye course kyun zaroori hai"),
      LessonBlock.paragraph("PPSC ke one paper me computer ke sawal har saal ate hain, aur ye sawal us hisse se ate hain jise aksar students sab se asaan samajh kar chor dete hain. Full form kya hai, RAM aur ROM me kya farq hai, aik GB me kitne MB hote hain, pehli generation me kya istemal hota tha — ye chhoti chhoti baatein hain, lekin paper me yehi number bante hain. Is lesson me hum computer ko bilkul shuru se samjhen ge, jese pehli dafa koi cheez seekhi jati hai. Pehle ye ke computer hai kya, phir us ke hisse, phir memory, phir generations, aur aakhir me internet ki buniyad aur full forms ki wo list jo paper me bar bar dohrai jati hai. Jo student ye lesson pakka kar le, one paper ke computer wale hisse ke aadhe sawal us ke liye muft ke number ban jayen ge."),
      LessonBlock.heading("Computer kya hai — pehle tareef samajh lo"),
      LessonBlock.paragraph("Dekho, sab se pehle ye zehen me bitha lo ke computer aik electronic machine hai jo hum se data leti hai, us par humari di hui hidayaat ke mutabiq kaam karti hai, aur phir humein result deti hai. Data wo kacha maal hai jo hum computer ko dete hain, jese numbers, naam, tasveerein ya awazein. Jab computer is kache data par kaam karke use kaam ki shakal de deta hai, to use information kehte hain. Misaal se samjho. Tum ne 40 students ke number computer ko diye, ye data hai. Computer ne bata diya ke sab se zyada number kis ke hain, kitne pass hue aur kitne fail, ye information hai. Paper me ye sawal bohat ata hai ke data aur information me kya farq hai, aur jawab yahi hai ke data kacha hota hai aur information kaam ki bani hui shakal."),
      LessonBlock.paragraph("Aik aur baat jo paper me poochi jati hai. Computer apne tor par kuch nahi soch sakta. Us ka apna dimagh nahi hota, wo sirf wahi karta hai jo use kaha jaye. Isi liye kehte hain ke computer ghalti nahi karta, ghalti hamesha use hidayaat dene wale insan ki hoti hai. Aur computer ki teen khaasiyat har paper me ghumti hain. Speed, yani wo bohat tez kaam karta hai, aik second me lakhon hisaab kar leta hai. Accuracy, yani us ka jawab durust hota hai. Aur storage, yani wo bohat sara data yaad rakh sakta hai aur saalon baad bhi waisa ka waisa nikaal deta hai."),
      LessonBlock.heading("Computer ke hisse — input devices"),
      LessonBlock.paragraph("Ab computer ke hisson ko samjho. Computer ka kaam teen marhalon me hota hai. Pehle data andar jata hai, phir us par kaam hota hai, phir result bahar ata hai. Jo cheezein data ko computer ke andar bhejne ke kaam ati hain, unhein input devices kehte hain. Sab se mashhoor input device keyboard hai, jis se hum likhte hain. Mouse dusri bari input device hai, jis se hum screen par ishara chalate hain aur cheezein chunte hain. Scanner kagaz par bani tasveer ya likhai ko computer ke andar digital shakal me bhejta hai. Microphone awaz ko andar bhejta hai, aur webcam chehra dikhane ke kaam ata hai. Paper me aksar ye ghumaya jata hai ke printer input hai ya output, to yaad rakho, printer result bahar nikalta hai, is liye wo output hai, input nahi."),
      LessonBlock.heading("Output devices — result kahan se ata hai"),
      LessonBlock.paragraph("Jo cheezein computer ke result ko humein dikhane ya sunane ke kaam ati hain, unhein output devices kehte hain. Monitor sab se bari output device hai, jo kuch hum karte hain wo screen par dikhata hai. Printer kagaz par result chhap kar deta hai, is chhapi hui shakal ko hard copy kehte hain, jabke screen par nazar ane wali shakal soft copy kehlati hai. Ye hard copy aur soft copy wala farq bhi paper me ata hai. Speaker aur headphone awaz sunate hain, is liye ye bhi output hain. Aik aham baat aur. Touch screen wali screen aik hi waqt me input bhi hai aur output bhi, kyunke hum use chhoo kar hidayaat bhi dete hain aur result bhi usi par dekhte hain. ATM ki screen aur mobile ki screen is ki behtareen misaalein hain."),
      LessonBlock.heading("CPU — computer ka dimagh"),
      LessonBlock.paragraph("Ab us hisse ki baat jo sab se zyada paper me ata hai. CPU ko computer ka dimagh kaha jata hai. CPU ka pura naam Central Processing Unit hai. Sari processing, yani sara hisaab kitab aur faisle, yahin hote hain. CPU ke andar do aham hisse hote hain. Pehla ALU, yani Arithmetic Logic Unit. Ye hisaab ka kaam karta hai, jama, tafreeq, zarb, taqseem, aur sath me mantaqi faisle bhi, jese bara hai ya chhota, barabar hai ya nahi. Dusra hisa Control Unit hai, jo pure computer ko control karta hai, kis hisse ne kab kya karna hai, is ka nazm o zabt isi ke pas hota hai. Paper me ye sawal seedha ata hai ke hisaab kitab computer ke kis hisse me hota hai, aur jawab hamesha ALU hai. Aik aur mashhoor sawal ye hai ke computer ka dimagh kisay kehte hain, jawab CPU hai."),
      LessonBlock.heading("Hardware aur software ka farq"),
      LessonBlock.paragraph("Ab aik buniyadi farq jo har paper me kisi na kisi shakal me ata hai. Computer ki wo cheezein jinhein hum chhoo sakte hain, dekh sakte hain aur utha sakte hain, unhein hardware kehte hain. Keyboard, mouse, monitor, printer, CPU ka dabba, ye sab hardware hain. Is ke baraks software wo program hote hain jo nazar to ate hain lekin chhooye nahi ja sakte. Jese Windows, MS Word, koi game ya mobile ki app. Asaan misaal ye hai ke hardware computer ka jism hai aur software us ki jaan hai. Jism baghair jaan ke bekaar hai aur jaan baghair jism ke kahin reh nahi sakti. Computer bhi aisa hi hai. Sirf hardware khareed lene se computer nahi chalta, use chalane ke liye software chahiye. Paper me ye sawal is shakal me bhi ata hai ke in me se konsi cheez software hai, aur options me Windows dekh kar pehchan lena ke yahi jawab hai."),
      LessonBlock.heading("System software aur application software"),
      LessonBlock.paragraph("Software ki do bari qismein hain, aur in ka farq paper ka pasandida sawal hai. Pehli qism system software hai. Is ka sab se bara naam Operating System hai, jisay mukhtasar OS kehte hain. Operating System wo software hai jo computer ko chalata hai, hardware aur user ke darmiyan pul ka kaam karta hai. Jab hum computer on karte hain to sab se pehle yahi chalta hai, aur jab tak ye na chale, koi aur program nahi chal sakta. Duniya me sab se zyada istemal hone wala operating system Microsoft Windows hai. Us ke ilawa macOS Apple ke computers me ata hai, aur Linux aik muft operating system hai. Mobile me Android aur iOS bhi operating system hi hain. Dusri qism application software hai. Ye wo program hain jo hum apne khaas kaamon ke liye istemal karte hain, jese likhne ke liye MS Word, hisaab ke liye MS Excel, presentation ke liye MS PowerPoint, aur tasveeron ke liye Photoshop. Yaad rakhne ka tareeqa ye hai ke operating system pure computer ke liye hai, aur application software kisi aik kaam ke liye hai."),
      LessonBlock.heading("Memory ki ikaiyan — bit se terabyte tak"),
      LessonBlock.paragraph("Ab wo hisaab jo one paper me har dafa ata hai. Computer har cheez ko numbers me yaad rakhta hai, aur us ki sab se chhoti ikai bit hai. Bit ka matlab aik 0 ya aik 1 hai, bas. Aath bit mil kar aik byte banta hai. Aik byte me aik harf, jese A ya B, store ho sakta hai. Is ke baad ikaiyan bari hoti jati hain, aur yahan paper ka asal jaal hai. Aik KB yani kilobyte me 1024 byte hote hain. Aik MB yani megabyte me 1024 KB hote hain. Aik GB yani gigabyte me 1024 MB hote hain. Aur aik TB yani terabyte me 1024 GB hote hain. Gaur karo, har qadam par 1000 nahi, 1024 hai. Yahi wo baat hai jis par aadhe students phas te hain, kyunke rozmarra ki zindagi me hum kilo ka matlab 1000 samajhte hain, lekin computer ki duniya me ye hisaab 2 ki taqat par chalta hai aur 1024 banta hai. Paper me sawal yun ata hai ke 1 GB me kitne MB hote hain, aur options me 1000 bhi hota hai aur 1024 bhi. Sahi jawab 1024 hai. Tartib yaad rakhne ke liye ye jumla zehen me rakho. Bit sab se chhota, phir Byte, phir KB, MB, GB, aur TB sab se bara."),
      LessonBlock.heading("RAM aur ROM ka farq"),
      LessonBlock.paragraph("Ab memory ki do qismein jinke farq par har paper me sawal banta hai. RAM ka pura naam Random Access Memory hai. Ye computer ki woh memory hai jisme wo cheezein rakhi jati hain jin par is waqt kaam ho raha hai. Jab tum MS Word kholte ho to wo RAM me ata hai, jab game chalti hai to wo bhi RAM me chalti hai. RAM ki sab se aham pehchan ye hai ke ye volatile hoti hai, yani bijli band hote hi is ka sara data mit jata hai. Computer band kiya to RAM khaali. Isi liye hum apna kaam save karte hain taake wo kahin pakki jagah chala jaye. Dusri taraf ROM hai, jis ka pura naam Read Only Memory hai. ROM ka data pakka hota hai, bijli jaye ya computer band ho, ye nahi mitta, is liye ise non volatile kehte hain. Is me computer ko start karne wali buniyadi hidayaat rakhi hoti hain, jo company ki taraf se pehle se likhi hoti hain. Paper me sawal yun ata hai ke konsi memory volatile hai, jawab RAM hai. Aur ye bhi poocha jata hai ke computer start karne ki hidayaat kahan hoti hain, jawab ROM hai. Aik jumle me yaad rakho. RAM kaam ke waqt ki meiz hai, cheezein wahan rakhi jati hain aur kaam khatam to meiz saaf. ROM wo almari hai jisme cheezein pakki pari rehti hain."),
      LessonBlock.heading("Storage devices — data pakka kahan rehta hai"),
      LessonBlock.paragraph("Jab hum file save karte hain to wo RAM se nikal kar storage device me chali jati hai, taake computer band hone ke baad bhi mehfooz rahe. Sab se purani aur aam storage device hard disk hai, jisay HDD kehte hain. Is me ghumne wali plates hoti hain aur is ki gunjaish bari hoti hai, aaj kal 500 GB se lekar kai TB tak milti hai. Is se tez aur nayi technology SSD hai, jis ka pura naam Solid State Drive hai. Is me koi ghumne wala hissa nahi hota, is liye ye hard disk se kai guna tez hoti hai aur computer chutkiyon me on ho jata hai. Paper me ye farq poocha jata hai ke SSD aur HDD me kya farq hai, aur jawab yahi hai ke SSD tez hai aur us me moving parts nahi hote. USB flash drive, jisay aam zubaan me USB ya flash kehte hain, jeb me ane wali chhoti storage hai. CD ki gunjaish takreeban 700 MB hoti hai aur DVD ki 4.7 GB hoti hai. Ye do adad paper me bar bar ate hain, inhein pakka yaad kar lo. CD aur DVD ko optical disc kehte hain kyunke inhein laser ki roshni se parha jata hai."),
      LessonBlock.heading("Computer ki generations — paanch dor"),
      LessonBlock.paragraph("Ab computer ki tareekh ko paanch generations me samjho, aur har generation ki pehchan us ke andar istemal hone wali cheez hai. Pehli generation 1940 se 1956 tak ki hai, is me vacuum tube istemal hote the. Ye computers bohat bare hote the, pure kamre me phail jate the, bohat bijli khate the aur bohat garam hote the. ENIAC is dor ka mashhoor computer hai. Dusri generation 1956 se 1963 tak ki hai, is me transistor aya. Transistor vacuum tube se chhota, sasta aur kam garam hota tha. Teesri generation 1964 se 1971 tak ki hai, is me IC yani Integrated Circuit aya, jis me bohat sare transistor aik chhoti si chip par ban jate the. Chauthi generation 1971 se ab tak samjhi jati hai, is me microprocessor aya, yani pura CPU aik hi chip par a gaya. Aaj ke tamam computers isi generation ke hain. Panchvi generation chal rahi hai aur is ki pehchan Artificial Intelligence yani AI hai, computer ka khud seekhna aur faisle karna. Paper me sawal yun banta hai ke microprocessor kis generation me aya, jawab chauthi hai. Aur vacuum tube pehli generation ki pehchan hai. Tartib yaad rakhne ke liye bas ye silsila zehen me rakho. Pehle tube, phir transistor, phir IC, phir microprocessor, aur ab AI."),
      LessonBlock.heading("Computer ki aqsaam"),
      LessonBlock.paragraph("Computer ki aqsaam do hisabon se poochi jati hain. Kaam ke tareeqe ke hisab se teen qismein hain. Digital computer wo hai jo numbers aur gin gin kar kaam karta hai, humara aam computer yahi hai. Analog computer naap tol se kaam karta hai, jese purana speedometer ya thermometer wali soch. Hybrid computer in dono ka mila jula hota hai, aksar hospitals aur science ke kaamon me istemal hota hai jahan naap bhi chahiye aur hisaab bhi. Paper me ye sawal ata hai ke humara rozmarra ka computer konsi qism hai, jawab digital hai. Dusri taraf size aur taqat ke hisab se sab se upar supercomputer hota hai. Ye duniya ke sab se tez aur mehange computer hote hain, mausam ki peshgoi, science ki bari research aur defence ke kaamon me lagte hain. Pakistan ke paper me ye bhi poocha jata hai ke supercomputer kis kaam ke liye hota hai, to mausam ki peshgoi wala jawab zehen me rakho."),
      LessonBlock.heading("Internet ki buniyad"),
      LessonBlock.paragraph("Ab internet ki wo buniyadi baatein jo one paper ka lazmi hissa hain. Internet duniya bhar ke computers ka aik bohat bara jaal hai, jis me sab aik dusre se jure hue hain. Is jaal ke upar jo service sab se zyada chalti hai use WWW kehte hain, yani World Wide Web. Aksar log internet aur WWW ko aik hi samajhte hain, lekin farq ye hai ke internet pura jaal hai aur WWW us jaal par chalne wali aik service hai. Ye farq paper me ata hai. Web par rakhi hui maloomat ko dekhne ke liye jo program istemal hota hai use browser kehte hain, jese Google Chrome, Mozilla Firefox aur Microsoft Edge. Aur maloomat dhundne ke liye jo website kaam ati hai use search engine kehte hain, jese Google, Bing aur Yahoo. Browser aur search engine ka farq bohat poocha jata hai. Browser wo darwaza hai jis se hum internet me dakhil hote hain, aur search engine wo rehnuma hai jo humein cheez dhund kar deta hai."),
      LessonBlock.paragraph("Isi silsile ki baqi baatein bhi pakki kar lo. Har website ka aik pata hota hai, use URL kehte hain, yani Uniform Resource Locator. Jese kisi ghar ka mukammal pata hota hai, wese hi URL website ka pata hai. Internet se jure har computer ki aik khaas number wali pehchan hoti hai, use IP address kehte hain. Website aur browser ke darmiyan maloomat ke len den ke usool ko HTTP kehte hain. Isi ka mehfooz wala roop HTTPS hai, jis me maloomat band aur mehfooz shakal me safar karti hai. Bank aur shopping wali websites par hamesha HTTPS hota hai, aur browser me aik chhota sa tala nazar ata hai. Paper me ye sawal ata hai ke HTTP aur HTTPS me S ka kya matlab hai, jawab Secure hai. Email electronic khat hai, jo internet ke zariye bheja jata hai, aur har email ka aik khaas address hota hai jis me @ ki alamat lazmi hoti hai. Aur Wi-Fi wo technology hai jo baghair taar ke, hawa ke zariye, computer aur mobile ko internet se jorti hai. Wi-Fi ka pura naam Wireless Fidelity mashhoor hai, ye bhi paper me ata hai."),
      LessonBlock.heading("Virus aur antivirus"),
      LessonBlock.paragraph("Aakhir is hisse me wo baat jo har saal kisi na kisi shakal me ati hai. Computer virus aik aisa chhota program hota hai jo khud ko computer me ghusa kar files ko kharab karta hai, data churata hai ya computer ko sust aur bekaar kar deta hai. Bilkul wese hi jese insan ke jism me virus bemari phailata hai. Ye aam tor par ghair mehfooz websites, nakli software aur ajnabi email attachments se ata hai. Is se bachao ke liye jo software istemal hota hai use antivirus kehte hain, jo virus ko pehchanta hai aur khatam karta hai. Paper me ye bhi poocha jata hai ke virus konsi qism ka software hai, to yaad rakho ye aik nuqsan deh program hai, operating system ya application ki aam fehrist me nahi ata. Aur aik aham usool ye hai ke jo email ya file kisi ajnabi ki taraf se aye, use khole baghair sochna chahiye, kyunke virus ka sab se aam rasta yahi hai."),
      LessonBlock.heading("Full forms ki mustanad list"),
      LessonBlock.paragraph("Ab wo list jo one paper me sab se zyada number deti hai. Full forms ko ratta lagane ke bajaye har aik ko us ke kaam ke sath jor kar yaad karo, phir ye kabhi nahi bhoolen gi. Main board par tartib se likh raha hun."),
      LessonBlock.example("CPU ka pura naam Central Processing Unit hai. Ye computer ka dimagh hai."),
      LessonBlock.example("ALU ka pura naam Arithmetic Logic Unit hai. Ye CPU ka wo hissa hai jahan hisaab hota hai."),
      LessonBlock.example("RAM ka pura naam Random Access Memory hai. Ye volatile memory hai, bijli jate hi saaf."),
      LessonBlock.example("ROM ka pura naam Read Only Memory hai. Ye pakki memory hai, start ki hidayaat yahin hoti hain."),
      LessonBlock.example("USB ka pura naam Universal Serial Bus hai. Flash drive aur dusri cheezein isi port se jurti hain."),
      LessonBlock.example("PDF ka pura naam Portable Document Format hai. Books aur forms ki files aksar isi me hoti hain."),
      LessonBlock.example("WWW ka pura naam World Wide Web hai. Ye internet par chalne wali web service hai."),
      LessonBlock.example("HTTP ka pura naam HyperText Transfer Protocol hai. Websites ka pata is se shuru hota hai."),
      LessonBlock.example("HTTPS me aakhir wala S Secure ka hai, yani mehfooz wala HTTP."),
      LessonBlock.example("HTML ka pura naam HyperText Markup Language hai. Web pages isi zubaan me bante hain."),
      LessonBlock.example("Wi-Fi ka pura naam Wireless Fidelity hai. Baghair taar internet jorne wali technology."),
      LessonBlock.example("LAN ka pura naam Local Area Network hai. Aik hi building ya office ke computers ka jaal."),
      LessonBlock.example("WAN ka pura naam Wide Area Network hai. Shehron aur mulkon tak phaila hua bara jaal, aur internet khud sab se bara WAN hai."),
      LessonBlock.example("GPS ka pura naam Global Positioning System hai. Satellite se jagah maloom karne wala nizam, mobile ke maps isi par chalte hain."),
      LessonBlock.example("URL ka pura naam Uniform Resource Locator hai. Ye har website ka pata hai."),
      LessonBlock.example("OS ka pura naam Operating System hai. Windows isi ki misaal hai."),
      LessonBlock.example("SSD ka pura naam Solid State Drive hai. Hard disk se tez wali nayi storage."),
      LessonBlock.example("HDD ka pura naam Hard Disk Drive hai. Purani aur aam storage device."),
      LessonBlock.example("IP ka pura naam Internet Protocol hai. IP address har computer ki number wali pehchan hai."),
      LessonBlock.example("AI ka pura naam Artificial Intelligence hai. Panchvi generation ki pehchan yahi hai."),
      LessonBlock.paragraph("Aakhir me aik mashwara zehen me rakho. Computer ke sawal one paper me mushkil nahi hote, bas bareek hote hain. 1000 aur 1024 ka farq, RAM ka volatile hona, browser aur search engine ka farq, ye teen chaar jaal hain jin me paper phasata hai. Inhein pakka kar lo to is hisse ke number tumhare pakke hain."),
    ],
  ),
  GeoTopic(
    id: "ms-word",
    title: "MS Word ka Complete Overview",
    subtitle: "Word ki window ka har kona, aur paper ke saare chhote sawal",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye overview kyun zaroori hai"),
      LessonBlock.paragraph("PPSC ke one paper me computer ke hisse me MS Word par har saal sawal ate hain. Aur aik baat gaur se sun lo. Ye sawal mushkil nahi hote, ye sawal chhote hote hain. Default font kya hai? Sab se bara font size kitna hota hai? Spelling check ki key konsi hai? File ki extension kya hai? Ye wo sawal hain jo sirf usi ko ate hain jis ne Word ko kabhi gaur se dekha ho. Jis ne kabhi Word khola hi nahi, wo in me phansta hai, chahe wo kitna hi parha likha kyun na ho."),
      LessonBlock.paragraph("Is overview ka maqsad ye hai ke tum Word ko is tarah samajh lo jese tum asal app ke samne bethe ho. Kaunsi cheez kahan milti hai, kis tab me milti hai, kis group me milti hai. Jab ye naqsha zehen me baith gaya to paper ke sawal khud bakhud asaan ho jayenge, kyunke har sawal isi naqshe se banta hai."),
      LessonBlock.heading("Word kya hai aur kis kaam ata hai"),
      LessonBlock.paragraph("Sab se pehle ye samajh lo ke MS Word hai kya. MS Word Microsoft company ka banaya hua aik word processor hai. Word processor ka matlab hai aisi app jis me tum likhai ka kaam karte ho. Khat likhna ho, application likhni ho, CV banana ho, report tayyar karni ho, kitab ka safha set karna ho, ye sab Word ka kaam hai. Microsoft Office ke package me jo apps ati hain, un me Word sab se zyada istemal hone wali app hai."),
      LessonBlock.paragraph("Ab file wali baat, kyunke ye paper ka fix sawal hai. Word me jo file banti hai usay document kehte hain. Har file ke naam ke aakhir me aik extension hoti hai jo batati hai ke ye kis app ki file hai. Purane versions me, yani Word 2003 aur us se pehle, extension .doc hoti thi. Word 2007 ke baad se extension .docx ho gayi hai. Docx ke aakhir wala x XML ki nishani hai, kyunke nayi file ka andar ka dhancha XML par bana hai. To ye jumla pakka yaad kar lo: Word 2007 aur us ke baad ki file .docx, us se pehle ki .doc. Paper me aksar yehi poocha jata hai aur aksar student purani wali .doc par nishan laga kar number kata leta hai."),
      LessonBlock.visual("Is hisse ki diagram me aik file ka icon dikhaya jaye jis ke neeche naam likha ho Report.docx, aur us ke sath doosra purana icon Report.doc, taake student ko dono extensions ka farq ankh se nazar ajaye."),
      LessonBlock.heading("Word ki window ke hisse"),
      LessonBlock.paragraph("Ab Word ko khol kar zehen me rakho aur aik aik hissa pehchano. Jab tum Word kholte ho to samne aik bari screen ati hai. Is screen ke har hisse ka aik naam hai aur paper me inhi naamon se sawal banta hai. Upar se shuru karte hain."),
      LessonBlock.paragraph("Sab se upar Title Bar hoti hai. Ye wohi patti hai jis par file ka naam likha nazar ata hai, jese Document1 ya tumhari file ka naam. Agar file abhi save nahi hui to wahan Document1 likha hota hai. Title Bar ke right kone par teen mashhoor button hote hain: Minimize, Maximize ya Restore, aur Close wala surkh X. Aur Title Bar ke left hisse me aik chhoti si patti hoti hai jisay Quick Access Toolbar kehte hain. Is par wohi button rakhe jate hain jo tum bar bar istemal karte ho. Aam tor par wahan Save, Undo aur Redo ke button pehle se hote hain. Paper me poocha jata hai ke Quick Access Toolbar kahan hoti hai, to jawab hai Title Bar par, upar left kone me."),
      LessonBlock.paragraph("Title Bar ke neeche jo bari patti hai, jis par saare button aur options lage hote hain, usay Ribbon kehte hain. Ribbon Word ka dil hai. Saari commands isi par sajti hain. Ribbon ke upar wali line me bade bade naam likhe hote hain: File, Home, Insert, Design, Layout, References, Mailings, Review, View. In me se har naam ko Tab kehte hain. Har tab ko dabane se us ke neeche us tab ki commands khul jati hain. Aur har tab ke andar commands chhote chhote khanon me banti hoti hain, in khanon ko Group kehte hain. Jese Home tab me Font group hai, Paragraph group hai. Har group ke neeche us ka naam bhi likha hota hai. Ye teen lafz pakke kar lo: upar Tab, tab ke andar Group, group ke andar commands. Paper ka aadha naqsha inhi teen lafzon par khara hai."),
      LessonBlock.paragraph("Har group ke right neeche kone me aik bohat chhota sa teer ka nishan hota hai. Isay Dialog Box Launcher kehte hain. Is ko dabane se us group ki poori settings wali window, yani dialog box, khul jati hai, jahan wo options bhi mil jate hain jo ribbon par jaga kam hone ki wajah se nazar nahi ate."),
      LessonBlock.paragraph("Ribbon ke neeche, document ke bilkul upar, aik scale type ki patti hoti hai jisay Ruler kehte hain. Ruler se tum margins dekh sakte ho, paragraph ka indent set kar sakte ho aur tab stops laga sakte ho. Ruler aam tor par inches me hota hai. Agar ruler nazar na aye to View tab se use on karte hain."),
      LessonBlock.paragraph("Beech wala bara safaid hissa Document Area hai. Ye tumhara asal safha hai, yahin tum likhte ho. Is safhe par jo chhoti si kaali lakeer timtimati hai, blink karti hai, usay Cursor ya Insertion Point kehte hain. Tum jo bhi type karoge, wohi se likhna shuru hoga jahan ye timtimati lakeer khari hai."),
      LessonBlock.paragraph("Screen ke right taraf aur neeche jo pattiyan hoti hain un se tum document me upar neeche aur dayen bayen ja sakte ho. Inhe Scroll Bar kehte hain. Right wali ko Vertical Scroll Bar aur neeche wali ko Horizontal Scroll Bar kehte hain."),
      LessonBlock.paragraph("Ab sab se neeche wali patti par ao, isay Status Bar kehte hain. Ye chhoti si patti bohat kaam ki khabrein deti hai. Is par page number likha ata hai ke tum kul kitne safhon me se kis safhe par ho, aur sath hi tumhare document ke kul alfaaz ki ginti, yani Word Count, har waqt nazar ati rehti hai. Status Bar ke right hisse me teen chhote button hote hain jinhe View Buttons kehte hain, un se tum document ko dekhne ka andaaz badalte ho. Aur un ke bilkul sath Zoom Slider hota hai, jisay dayen bayen karne se safha bara ya chhota nazar ata hai. Paper me ye sawal bohat ata hai ke word count kahan nazar ata hai. Jawab Status Bar hai. Bas, ye jumla rat lo."),
      LessonBlock.visual("Is hisse ki diagram me poori Word window ki tasveer ho aur har hisse par number laga ho — 1 Title Bar, 2 Quick Access Toolbar, 3 Ribbon, 4 Tab, 5 Ruler, 6 Document Area, 7 Cursor, 8 Scroll Bar, 9 Status Bar, 10 Zoom Slider — aur neeche har number ke samne us hisse ka naam likha ho, bilkul wese jese is overview ke sample naqshay me hota hai."),
      LessonBlock.heading("Har tab me kya milta hai"),
      LessonBlock.paragraph("Ab ribbon ke har tab ko aik aik karke pehchano. Ye woh hissa hai jahan se paper ke sab se zyada sawal bante hain, kyunke examiner poochta hai ke falaan cheez kis tab me hai."),
      LessonBlock.paragraph("File tab sab se pehla tab hai aur ye baqiyon se alag hai. Ise dabane se ribbon nahi khulta, poori aik screen khulti hai jisay Backstage View kehte hain. Yahan file ke bare me kaam hote hain: New yani nayi file, Open yani purani file kholna, Save, Save As, Print, Share aur Export. File ki info bhi yahin milti hai. Yaad rakho, File tab document ke andar ka kaam nahi karta, file ke upar ka kaam karta hai."),
      LessonBlock.paragraph("Home tab woh tab hai jo Word khulte hi samne hota hai aur sab se zyada istemal hota hai. Likhai ko sajana sanwarna, font badalna, size bara karna, rang lagana, line set karna, ye sab Home tab ka kaam hai. Iski tafseel agle hisse me ayegi kyunke ye tab paper ke liye sab se aham hai."),
      LessonBlock.paragraph("Insert tab ka kaam hai document ke andar cheezain dalna. Table dalna ho, tasveer dalni ho, shape banana ho, chart, SmartArt, header footer, page number, symbol ya equation, sab kuch Insert tab me milta hai."),
      LessonBlock.paragraph("Design tab document ki shakal aur sajawat ke liye hai. Themes, rangon ke set, fonts ke set aur page ka background. Aur aik trap yahan pakka kar lo: Watermark, yani safhe ke peeche halka sa likha hua lafz jese CONFIDENTIAL, wo Design tab me hota hai, Insert me nahi. Purane Word 2010 me watermark Page Layout tab me hota tha, lekin Word 2016 aur 365 me ye Design tab me hai aur paper me aaj kal isi naye wale ko sahi mana jata hai."),
      LessonBlock.paragraph("Layout tab safhe ki setting ke liye hai. Page ka size, orientation, margins, columns, ye sab Layout tab me milta hai. Word 2013 tak is tab ka naam Page Layout tha, 2016 ke baad sirf Layout reh gaya. Paper me agar Page Layout likha aye to ghabrana nahi, wohi Layout tab hai."),
      LessonBlock.paragraph("References tab lambay aur ilmi documents ke liye hai. Table of contents banana, footnote dalna, citation aur bibliography set karna, ye sab yahan hota hai. Thesis aur kitab likhne wale is tab ko bohat istemal karte hain."),
      LessonBlock.paragraph("Mailings tab ka khaas kaam Mail Merge hai. Is ki tafseel aage alag hisse me ayegi."),
      LessonBlock.paragraph("Review tab parhai aur jaanch ka tab hai. Spelling aur grammar ki ghaltiyan dekhna, comments lagana, track changes, aur document ko compare karna, ye sab Review tab me hai."),
      LessonBlock.paragraph("View tab document ko dekhne ke andaaz ka tab hai. Alag alag views, zoom, ruler on off karna, aur aik se zyada windows ko sath dikhana, ye sab View tab se hota hai."),
      LessonBlock.visual("Is hisse ki diagram me ribbon ki aik lambi patti dikhayi jaye jis par saare tabs ke naam hon, aur har tab ke neeche aik line me likha ho ke is me kya milta hai, taake student aik nazar me poora naqsha dekh le."),
      LessonBlock.heading("Home tab ki tafseel"),
      LessonBlock.paragraph("Ab Home tab ko khol kar zehen me rakho, kyunke ye tab tum roz istemal karoge aur paper me is par sab se zyada sawal hain. Home tab me aam tor par paanch group hote hain: Clipboard, Font, Paragraph, Styles aur Editing."),
      LessonBlock.paragraph("Font group me likhai ki shakal badli jati hai. Yahan tum font chun sakte ho, yani likhai ka andaaz, size bara chhota kar sakte ho, aur text ko Bold, Italic ya Underline kar sakte ho. Bold matlab mota likha hua, is ki key Ctrl+B hai. Italic matlab terha likha hua, key Ctrl+I. Underline matlab neeche lakeer, key Ctrl+U. Ye teenon key paper me bar bar poochi jati hain. Font group me hi font ka rang badalne aur highlight karne ke options bhi hote hain. Font wali bari window kholne ki key Ctrl+D hai, ye bhi yaad rakhne wali hai."),
      LessonBlock.paragraph("Paragraph group me lines aur paragraphs ki setting hoti hai. Sab se aham cheez alignment hai, yani text kis taraf set hai. Alignment chaar tarah ki hoti hai. Left alignment me text bayen taraf se seedha hota hai aur dayen taraf tera mera, ye aam likhai ke liye hota hai, key Ctrl+L. Center alignment me text beech me ata hai, heading ke liye istemal hota hai, key Ctrl+E. Right alignment me text dayen taraf se seedha hota hai, key Ctrl+R. Aur Justify me text dono taraf se seedha ho jata hai, bilkul akhbaar ke column ki tarah, key Ctrl+J. Ye chaar naam aur in ki keys paper ke fix sawal hain."),
      LessonBlock.paragraph("Isi Paragraph group me line spacing hoti hai, yani do lines ke darmiyan kitna faasla ho. Aur bullets aur numbering bhi yahin milte hain. Bullets matlab points ke aage gole nishan, aur numbering matlab points ke aage 1, 2, 3 wale number. Indent, yani paragraph ko bayen ya dayen khiskana, bhi isi group ka kaam hai."),
      LessonBlock.paragraph("Styles group me tayyar shuda styles hote hain. Style matlab font, size, rang aur spacing ka pehle se set kiya hua jora. Normal style aam text ke liye hai. Heading 1 sab se bari heading ke liye, Heading 2 us se chhoti heading ke liye. Aik hi click me poore paragraph ki shakal badal jati hai. Paper me poocha jata hai ke heading lagane ke liye konsa group istemal hota hai, to jawab Styles group hai, Home tab me."),
      LessonBlock.paragraph("Editing group Home tab ke bilkul aakhir me hota hai. Is me Find, Replace aur Select hote hain. In ki tafseel bhi aage ayegi."),
      LessonBlock.visual("Is hisse ki diagram me Home tab ka ribbon bara karke dikhaya jaye, Font group aur Paragraph group par ghaira bana ho, aur neeche alignment ki chaar misalein chhote chhote khanon me hon — left, center, right aur justify — taake student ko chaaron ka farq ankh se samajh ajaye."),
      LessonBlock.heading("Font size wali khaas tafseel"),
      LessonBlock.paragraph("Ab wo hissa jo paper ke liye sab se khaas hai. Font size. Dekho, Home tab ke Font group me size wali aik chhoti si khirki hoti hai jis me aik number likha hota hai, aam tor par 11. Us ke sath aik teer hota hai. Teer dabane se aik list khulti hai. Is tayyar list me sizes 8 se lekar 72 tak hote hain. 8, 9, 10, 11, 12, 14, 16, is tarah barhte hue 72 tak. Aksar student yehi samajhta hai ke Word me sab se bara size 72 hai. Yehi wo jaal hai jis me paper phansata hai."),
      LessonBlock.paragraph("Asal baat ye hai ke tum us khirki me khud number type bhi kar sakte ho. Aur type karke tum 1 se lekar 1638 tak koi bhi size de sakte ho. To Word me sab se chhota font size 1 hai aur sab se bara font size 1638 hai. Ye jumla paper ka fix sawal hai, isay zehen me pakka baitha lo. Jab paper me sawal aye ke MS Word me maximum font size kitna hota hai, to options me 72 bhi hoga, 100 bhi hoga, lekin sahi jawab 1638 hai."),
      LessonBlock.paragraph("Ab default wali baat. Jab tum Word me nayi file kholte ho to jo font pehle se set hota hai usay default font kehte hain. Word 2016 aur 365 me default font Calibri hai aur default size 11 hai. Bohat purane Word 2003 me default font Times New Roman size 12 hota tha, lekin aaj kal ke paper me Calibri 11 hi sahi jawab mana jata hai. Aur aik phanday se bachna. Heading styles me jo bara size nazar ata hai, wo font size ki had nahi hai. Had sirf wohi hai jo type karke di ja sakti hai, yani 1638."),
      LessonBlock.visual("Is hisse ki diagram me font size wali khirki bari karke dikhayi jaye, us ki khuli hui list me 8 se 72 tak ke number hon, aur sath aik doosri tasveer ho jis me usi khirki me 1638 type kiya gaya ho aur neeche aik bohat bara sa lafz likha nazar aye, taake student ko yaad rahe ke list wali had asal had nahi hai."),
      LessonBlock.heading("Page setup ki baatein"),
      LessonBlock.paragraph("Ab safhe ki setting samajh lo. Ye Layout tab ke Page Setup group se hoti hai."),
      LessonBlock.paragraph("Pehli cheez page size hai. Word me do size sab se zyada chalte hain. Aik A4 hai, jo Pakistan me aur duniya ke zyadatar mulkon me standard hai. A4 ki lambai chorai 210 guna 297 millimeter hoti hai, inchon me taqreeban 8.27 guna 11.69. Doosra Letter hai, jo America me chalta hai, 8.5 guna 11 inch. A4 Letter ke muqable me thora lamba aur thora kam chora hota hai. Paper me ye farq poocha jata hai."),
      LessonBlock.paragraph("Doosri cheez orientation hai, yani safha khara hai ya leta hua. Jab safha seedha khara ho, lambai zyada aur chorai kam, to use Portrait kehte hain. Aam documents portrait me hi bante hain. Jab safha leta hua ho, chorai zyada aur lambai kam, to use Landscape kehte hain. Bari tables aur tasveeron wale safhe landscape me ache lagte hain."),
      LessonBlock.paragraph("Teesri cheez margins hain. Margin matlab safhe ke chaaron kinaron par chhori gayi khaali jaga. Upar neeche dayen bayen. Word me default margin chaaron taraf 1 inch hota hai. Ye bhi paper ka fix sawal hai. Purane Word 2003 me upar neeche 1 inch aur dayen bayen 1.25 inch hota tha, lekin naye Word me chaaron taraf barabar 1 inch hai, aur paper me yehi jawab chalta hai."),
      LessonBlock.visual("Is hisse ki diagram me do safhe sath sath dikhaye jayen — aik portrait me khara aur aik landscape me leta hua — aur teesre safhe par chaaron taraf margin wali jaga halke rang se bhari hui ho aur teeron se 1 inch likha ho."),
      LessonBlock.heading("Insert tab aur table ki baatein"),
      LessonBlock.paragraph("Insert tab ka kaam pehle bata chuka hun ke document ke andar cheezain dalna hai. Ab in cheezon ko aik aik karke pehchano."),
      LessonBlock.paragraph("Table dalna Insert tab ka sab se mashhoor kaam hai. Table matlab khanon wali chart, jese time table hota hai. Table me jo khari lines wale hisse hote hain unhe Column kehte hain, aur jo leti lines wale hisse hote hain unhe Row kehte hain. Row aur column ke milne se jo chhota khana banta hai usay Cell kehte hain. Ye teen lafz pakke kar lo: Row, Column, Cell. Jab tum Insert tab se table dalte ho to ribbon par do naye tab khul jate hain jinhe Table Tools kehte hain, Design aur Layout. In se tum table ko rang de sakte ho, lines badal sakte ho, do cells ko jor kar aik kar sakte ho jisay Merge kehte hain, aur aik cell ko tod kar do bana sakte ho jisay Split kehte hain. Jab poora table select karna ho to table ke upar bayen kone par aik chhota sa plus jaisa nishan ata hai, use dabane se poora table select ho jata hai."),
      LessonBlock.paragraph("Insert tab se hi tum document me Picture yani tasveer dal sakte ho, Shapes yani gole, chaukor, teer jaisi shaklein bana sakte ho, aur Chart dal sakte ho. Header aur Footer ke buttons bhi Insert tab me hote hain, in ki tafseel thori aage ayegi. Page Number dalne ka button bhi Insert tab me hai. Symbol dalna, yani wo nishan jo keyboard par nahi hote jese copyright wala ya degree wala nishan, wo bhi Insert tab ke aakhir me Symbol se milta hai. Aur hisaab ke sawal likhne ke liye Equation ka option bhi Insert tab me hi hota hai."),
      LessonBlock.paragraph("Aik baar phir wo trap dohra dun. Watermark Insert tab me nahi hai. Watermark Design tab me hai. Paper me ye jaan boojh kar Insert ke options me rakha jata hai aur bohat se student wahi phanste hain."),
      LessonBlock.visual("Is hisse ki diagram me aik chhoti si table dikhayi jaye jis par row par teer, column par teer aur aik cell ke gird ghaira bana ho, taake teeno lafzon ka farq ankh se wazeh ho jaye. Sath Insert tab ke mashhoor buttons ke chhote icon bhi dikhaye jayen."),
      LessonBlock.heading("Find, Replace, Spelling aur Thesaurus"),
      LessonBlock.paragraph("Ab wo tools jo likhai ki jaanch aur tabdeeli ke liye hain. Ye Home tab ke Editing group me bhi milte hain aur in ki shortcut keys paper ki jaan hain."),
      LessonBlock.paragraph("Find ka matlab hai document me koi lafz dhundna. Is ki key Ctrl+F hai. Ise dabane se bayen taraf aik khana khul jata hai jahan tum lafz likhte ho aur Word tumhe bata deta hai ke wo lafz kahan kahan aya hai."),
      LessonBlock.paragraph("Replace ka matlab hai aik lafz ko dhund kar us ki jagah doosra lafz rakh dena, pure document me aik sath. Is ki key Ctrl+H hai. Farz karo tum ne pure document me Ahmad likha tha aur ab use Ahmed karna hai. Replace se aik click me har jagah badal jayega. Find aur Replace ka farq paper me bohat ata hai. Sirf dhundna hai to Ctrl+F, dhund kar badalna hai to Ctrl+H."),
      LessonBlock.paragraph("Ab spelling ki jaanch. Jab tum Word me koi lafz ghalat likhte ho to us ke neeche aik surkh rengti hui lakeer, zigzag line, ajati hai. Is ka matlab hai spelling ki ghalti. Agar grammar ki ghalti ho, yani jumla banaan ke hisab se ghalat ho, to neeche neeli ya sabz lakeer ati hai. Purane versions me grammar ke liye sabz lakeer thi, naye Word me neeli ho gayi hai. Aur aik teesri lakeer bhi hoti hai, neeli wali jo kabhi kabhi jumle ki wazehiyat par ishara karti hai. In lakeeron ko dekh kar hi pata chal jata hai ke ghalti kis qism ki hai."),
      LessonBlock.paragraph("Poore document ki spelling aur grammar aik sath check karne ke liye F7 dabate hain. F7 Review tab ke Spelling and Grammar wale kaam ko khol deta hai. Ye key paper me lazmi poochi jati hai. Aur is ke sath aik aur key jor kar yaad kar lo: Shift+F7. Shift+F7 se Thesaurus khulta hai. Thesaurus matlab kisi lafz ke hum maani alfaaz, yani synonyms, aur mukhalif maani alfaaz ki fehrist. Jab tumhe kisi lafz ki jagah behtar lafz chahiye ho to Thesaurus kaam ata hai. To ye jora rat lo: F7 spelling aur grammar, Shift+F7 Thesaurus."),
      LessonBlock.visual("Is hisse ki diagram me aik jumla dikhaya jaye jis me aik lafz ke neeche surkh zigzag lakeer ho aur doosre hisse ke neeche neeli lakeer, aur neeche likha ho ke surkh matlab spelling ki ghalti aur neeli matlab grammar ki. Sath F7 aur Shift+F7 ki keys keyboard par numaya karke dikhayi jayen."),
      LessonBlock.heading("Mail Merge kya hai"),
      LessonBlock.paragraph("Ab Mailings tab ka wo kaam jo naam sun kar bohaton ko mushkil lagta hai lekin hai bohat asaan. Mail Merge."),
      LessonBlock.paragraph("Farz karo aik school ko 500 students ke parents ko result ki chitthi bhejni hai. Har chitthi me school ka wohi purana text hoga, bas student ka naam, class aur number alag honge. Agar tum 500 chitthiyan alag alag likho to din lag jayega. Mail Merge ye karta hai ke tum aik hi asal khat likhte ho, aur naamon wali list alag se bana lete ho, phir Word khud har naam ke liye alag chitthi tayyar kar deta hai. Yani aik likhai, bohat se log. Merge ka matlab hai milana — asal khat aur naamon ki list ko mila dena."),
      LessonBlock.paragraph("Mail Merge Mailings tab me hota hai. Wahan Start Mail Merge se kaam shuru hota hai, phir Select Recipients se naamon wali list jori jati hai, jo aam tor par Excel ki file ya Word ki table me hoti hai. Phir khat me jaga jaga naam wale khaali khane, jinhe merge fields kehte hain, rakhe jate hain. Aakhir me Finish and Merge se saari chitthiyan tayyar ho jati hain."),
      LessonBlock.paragraph("Paper me Mail Merge is liye ata hai kyunke ye Word ka sab se mashhoor khaas kaam hai aur examiner poochta hai ke ye kis tab me hota hai aur is se kya hota hai. Jawab yaad rakho: Mailings tab, aik hi document bohat se logon ke liye, har aik ke naam ke sath."),
      LessonBlock.visual("Is hisse ki diagram me aik taraf aik asal khat dikhaya jaye jis me naam ki jaga khaali khana ho, doosri taraf naamon ki chhoti si list ho, aur beech me aik teer ja kar teen alag alag chitthiyan banata hua nazar aye, taake mail merge ka khayal aik nazar me samajh ajaye."),
      LessonBlock.heading("Header, Footer aur Page Number"),
      LessonBlock.paragraph("Har safhe ke upar wale hisse ko Header kehte hain aur neeche wale hisse ko Footer kehte hain. Header me aam tor par kitab ka naam, chapter ka naam ya school ka naam likha jata hai jo har safhe par khud bakhud ata rehta hai. Tumhe har safhe par alag se likhna nahi parta, aik dafa header me likh do to har safhe par wahi nazar ayega. Footer me aam tor par page number dala jata hai."),
      LessonBlock.paragraph("Page number dalne ke liye Insert tab me Page Number ka button hai. Wahan se tum chun sakte ho ke number safhe ke upar aye ya neeche, bayen aye ya beech me ya dayen. Header aur Footer me ja kar tum khud bhi number aur text dal sakte ho. Jab tum header ya footer me kaam kar rahe hote ho to asal document halka sa dhundla ho jata hai, aur bahar click karne se tum wapas asal text me ajate ho."),
      LessonBlock.paragraph("Paper me ye sawal ata hai ke page number kis tab se dala jata hai. Jawab Insert tab hai. Aur header footer kahan hote hain, safhe ke sab se upar aur sab se neeche wale margin wale hisse me."),
      LessonBlock.visual("Is hisse ki diagram me aik safha dikhaya jaye jis ke upar wale hisse par ghaira bana kar Header likha ho, beech me asal text halka ho, aur neeche wale hisse par ghaira bana kar Footer likha ho jahan page number 5 nazar araha ho."),
      LessonBlock.heading("Zoom aur Views"),
      LessonBlock.paragraph("Ab document ko dekhne ki baatein. Pehle zoom. Zoom ka matlab hai safhe ko screen par bara ya chhota karke dekhna. Is se asal print par koi farq nahi parta, sirf tumhari screen par safha bara ya chhota nazar ata hai. Zoom status bar ke right kone par slider se badla jata hai, aur View tab me Zoom ka button bhi hota hai. Word me zoom sab se kam 10 percent aur sab se zyada 500 percent hota hai. Ye bhi paper ka fix sawal hai. Aam halat me zoom 100 percent hota hai."),
      LessonBlock.paragraph("Ab views. View matlab document ko dekhne ka andaaz. Word me paanch views hote hain aur ye View tab se aur status bar ke view buttons se badle jate hain."),
      LessonBlock.paragraph("Pehla Print Layout hai. Ye woh view hai jo Word khulte hi samne hota hai, yani ye default view hai. Is me safha bilkul wesa nazar ata hai jesa print hokar niklega, margins aur header footer ke sath. Paper ka fix sawal hai ke Word ka default view konsa hai, jawab Print Layout."),
      LessonBlock.paragraph("Doosra Read Mode hai. Ye parhne ke liye hai. Is me safha kitab ki tarah khul jata hai aur editing ke button ghayab ho jate hain taake tum sukoon se parh sako."),
      LessonBlock.paragraph("Teesra Web Layout hai. Is me document wesa nazar ata hai jesa kisi website ke safhe par nazar ayega, bina safhon ki taqseem ke."),
      LessonBlock.paragraph("Chautha Outline hai. Ye lambay document ki headings ko khaaka bana kar dikhata hai, taake poore document ka dhancha aik nazar me samajh ajaye."),
      LessonBlock.paragraph("Paanchwan Draft hai. Ye saada view hai jis me header footer aur margins nazar nahi ate, sirf text hota hai. Tez likhne ke liye ye acha rehta hai."),
      LessonBlock.visual("Is hisse ki diagram me aik hi safha paanch chhote khanon me alag alag views me dikhaya jaye — Print Layout, Read Mode, Web Layout, Outline aur Draft — aur Print Layout wale khane par sitara laga ho ke ye default hai. Sath zoom slider ki tasveer ho jis par 10 percent aur 500 percent ke nishan hon."),
      LessonBlock.heading("Print aur Save"),
      LessonBlock.paragraph("Ab aakhir ke do kaam, jo har file ke sath hote hain: save karna aur print karna."),
      LessonBlock.paragraph("Save ka matlab hai apni file ko mehfooz kar lena taake baad me phir khul sake. Save ki key Ctrl+S hai. Pehli dafa save karne par Word tum se file ka naam aur jaga poochta hai. Agar tum file ko naye naam se ya doosri jaga save karna chahte ho to Save As istemal hota hai, jis ki key F12 hai. Ye F12 wali key paper me bohat poochi jati hai, isay pakka kar lo. Save As se hi tum file ko .docx ki bajaye PDF me bhi save kar sakte ho. PDF aisi file hoti hai jo har computer par aik jaisi khulti hai aur us me tabdeeli asaan nahi hoti, is liye CV aur applicationain aksar PDF me bheji jati hain. File tab ke Export se bhi PDF banayi ja sakti hai."),
      LessonBlock.paragraph("Print ka matlab hai document ko kaghaz par nikalna. Print ki key Ctrl+P hai. Ise dabane se print wali screen khulti hai jahan tum pehle Print Preview dekh sakte ho, yani print se pehle safha wesa hi dekh sakte ho jesa kaghaz par niklega. Wahan tum chun sakte ho ke kitni copies chahiye, konse safhe print hon, aur printer konsa ho. Ye teen keys ka set aik sath yaad kar lo: Ctrl+S save, F12 save as, Ctrl+P print."),
      LessonBlock.paragraph("Aur aakhir me word count wali baat aik dafa phir. Tumhare document me kul kitne alfaaz hain, ye har waqt Status Bar par likha nazar ata rehta hai. Agar tumhe poori tafseel chahiye, kitne safhe, kitne alfaaz, kitne characters, to Status Bar ke usi word count par click karne se poori window khul jati hai. Review tab me bhi Word Count ka button hota hai. Paper me poocha jata hai word count kahan dikhta hai, to pehla jawab Status Bar hai."),
      LessonBlock.visual("Is hisse ki diagram me teen keys bari bari dikhayi jayen — Ctrl+S ke sath Save, F12 ke sath Save As aur Ctrl+P ke sath Print likha ho — aur neeche status bar ki patti ho jis par page number aur word count numaya karke dikhaye gaye hon."),
      LessonBlock.heading("Paper ke fix facts"),
      LessonBlock.paragraph("Ab is pure overview ka nichor aik jagah jama kar lo. Ye wo jumle hain jo paper me seedhe seedhe sawal ban kar ate hain. Inhe is tarah yaad karo jese ye tumhare liye likhe gaye hon."),
      LessonBlock.paragraph("Word ki file ki extension .docx hai, jo 2007 ke baad se hai, aur us se pehle .doc thi. Nayi khaali file ka naam Document1 hota hai. Word ka default font Calibri hai aur default size 11 hai. Font size ki tayyar list 8 se 72 tak jati hai, lekin type karke 1 se 1638 tak diya ja sakta hai, to sab se bara font size 1638 hai. Default margin chaaron taraf 1 inch hai. A4 ka size 210 guna 297 millimeter hai aur Letter 8.5 guna 11 inch. Zoom sab se kam 10 percent aur sab se zyada 500 percent hota hai. Word ka default view Print Layout hai."),
      LessonBlock.paragraph("Keys wale facts ye hain. Spelling aur grammar check F7 hai. Thesaurus Shift+F7 hai. Find Ctrl+F, Replace Ctrl+H. Save Ctrl+S, Save As F12, Print Ctrl+P. Bold Ctrl+B, Italic Ctrl+I, Underline Ctrl+U. Alignment ki keys: Left Ctrl+L, Center Ctrl+E, Right Ctrl+R, Justify Ctrl+J."),
      LessonBlock.paragraph("Jagah wale facts ye hain. Word count Status Bar par nazar ata hai. Quick Access Toolbar Title Bar par hoti hai. Watermark Design tab me hai, Insert me nahi. Mail Merge Mailings tab me hai. Page number Insert tab se dalta hai. Spelling check Review tab me bhi hai aur F7 se bhi khulta hai."),
      LessonBlock.paragraph("Aur alfaaz wale facts. Table ki khari taqseem Column, leti taqseem Row, aur dono ke milne ka khana Cell hai. Safhe ke upar wala hissa Header aur neeche wala Footer hai. Do cells ko jorna Merge aur aik ko todna Split hai. Spelling ki ghalti par surkh zigzag lakeer ati hai, grammar ki ghalti par neeli lakeer. Jo ye saare jumle pakke kar le, us ke liye Word ke sawal paper ke sab se asaan number ban jate hain."),
    ],
  ),
  GeoTopic(
    id: "ms-excel",
    title: "MS Excel ka Complete Overview",
    subtitle: "Excel. Hisaab kitab wali sheet, aur paper ke sab se pakke number",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye overview kyun zaroori hai"),
      LessonBlock.paragraph("PPSC ke one paper me computer ke hisse me MS Excel par har saal sawal ate hain, aur mazay ki baat ye hai ke Excel ke sawal taqreeban fix hote hain. Rows kitni hain, columns kitne hain, aakhri column konsa hai, formula kis nishan se shuru hota hai, SUM aur AVERAGE kya karte hain. Ye wo sawal hain jo ratta nahi mangte, bas aik dafa screen ko samajh kar dekh lena mangte hain. Jo student is overview ko pakka kar le, wo Excel ke hisse me number nahi katay ga, kyunke yahan ghalti concept ki nahi hoti, chhoti chhoti facts bhoolne ki hoti hai. Isi liye har cheez pehle samjhai jayegi, phir bataya jayega ke screen par wo milti kahan hai, aur aakhir me wo fix fact diya jayega jo paper me seedha poocha jata hai."),
      LessonBlock.heading("Pehle Excel ko samajh lo"),
      LessonBlock.paragraph("Dekho, sab se pehle Excel ko samajh lo, baqi sab khud asaan ho jayega. Apne mohallay ke karyana store wale ka wo bara register yaad karo jisme wo hisaab likhta hai. Khane bane hote hain, har cheez apne khane me, aur aakhir me jama ghata khud hi ho jata hai jab wo calculator nikalta hai. Excel bas usi register ki electronic shakal hai, farq sirf itna hai ke yahan calculator register ke andar hi chhupa hai."),
      LessonBlock.paragraph("Excel Microsoft Office ka wo program hai jo hisaab kitab ke liye bana hai. Ise angrezi me spreadsheet kehte hain. Spreadsheet ka matlab hai khanon wali bari sheet jis par number likhe jate hain aur un par hisaab hota hai. School ka result banana ho, daftar ka budget ho, dukaan ka mahana hisaab ho ya mulazimon ki tankhwah ki list, jahan bhi numberon ki list aur un par jama, ghata, ausat nikalna ho, wahan Excel kaam ata hai. Word me hum likhte hain, Excel me hum gin-te hain. Ye aik line zehen me bitha lo, aadha concept yahin clear ho gaya."),
      LessonBlock.visual("Aik karyana store ke purane hisaab wale register aur us ke sath wali Excel ki screen ka muqabla. Register ke khane aur Excel ke khane aik jaise rang me dikhaye jayen, aur register ke sath rakha calculator Excel ke andar chhupa dikhaya jaye, taake student ko pehli nazar me samajh aye ke Excel asal me hai kya."),
      LessonBlock.heading("File ki pehchan, extension aur default naam"),
      LessonBlock.paragraph("Jab tum nayi Excel file kholte ho to upar us ka naam Book1 likha ata hai. Book1 Excel ki har nayi khali file ka default naam hai, jab tak tum khud save karke apna naam na de do. Ye chhoti si baat paper me poochi ja chuki hai, is liye isay halka mat lo."),
      LessonBlock.paragraph("Ab extension ki baat. Extension file ke naam ke aakhir me wo chhota sa hissa hai jo batata hai ke file kis program ki hai, jese naam ke sath lagne wala khandan ka naam. Excel 2003 aur us se pehle ke zamane me Excel file ki extension .xls hoti thi. Phir 2007 me Microsoft ne naya format nikala aur extension .xlsx ho gayi. Is x ka matlab hai ke file andar se naye XML wale format me bani hai. Aaj ke Excel 2016 aur Microsoft 365 me default extension .xlsx hi hai, aur paper me jab Excel ki extension poochi jati hai to sahi jawab .xlsx hi banta hai. Lekin khabardar, kuch purani kitabon aur purane papers me .xls bhi jawab ata raha hai, kyunke wo sawal purane zamane ke hain. Usool yaad rakho, 2007 se pehle .xls, 2007 ke baad .xlsx. Sawal me version ka zikr ho to usi hisab se jawab do, na ho to naya wala yani .xlsx chuno."),
      LessonBlock.visual("Do file icon sath sath. Aik par purana label .xls aur neeche 2003 likha ho, dusre par naya label .xlsx aur neeche 2007 ke baad likha ho. Darmiyan me aik teer jo purane se naye ki taraf ishara kare, taake saal wala farq aik nazar me zehen me beth jaye."),
      LessonBlock.heading("Workbook aur Worksheet ka farq"),
      LessonBlock.paragraph("Ab wo farq samjho jis par paper sab se zyada phansata hai. Workbook aur worksheet sunne me aik jaise lagte hain, lekin hain bilkul alag cheezain."),
      LessonBlock.paragraph("Workbook poori file ko kehte hain. Wapas register wali misaal par ao. Poora register aik workbook hai. Aur worksheet us register ka aik warq hai, aik sheet. Aik workbook ke andar kai worksheets ho sakti hain, jese register me kai warq hote hain. Tum neeche dekho ge to sheeton ke naam tabs ki shakal me nazar ayenge, Sheet1, Sheet2 waghera. Kisi bhi tab par click karo, wo sheet khul jati hai. Nayi sheet jorne ke liye tabs ke sath bane plus wale nishan par click karte hain, aur sheet ka naam badalna ho to tab par double click karke apna naam likh dete hain, jese January ka Hisab. Sheet ke naam ki aik fix hadd bhi hai, sheet ka naam zyada se zyada 31 characters ka ho sakta hai. Ye 31 wala number paper me ata hai, yaad rakho."),
      LessonBlock.paragraph("Ab asal trap suno. Nayi workbook kholne par andar pehle se kitni sheets hoti hain? Aaj ke Excel 2016 aur 365 me jawab hai aik, sirf aik sheet. Lekin purani kitabein teen likhti hain, kyunke Excel 2010 aur us se pehle default teen sheets hoti thi. Dono jawab apni apni jagah sahi hain, farq version ka hai. Paper me agar sirf ye poocha jaye ke nayi workbook me kitni sheets hoti hain aur options me aik aur teen dono hon, to aaj ke hisab se aik wala jawab durust mana jata hai, lekin agar sawal purane Excel ka zikr kare to teen. Yehi wo nuqta hai jahan aadhe students phans jate hain. Aik aur baat, sheets ki zyada se zyada tadaad ki koi fix hadd nahi, ye computer ki memory par munhasir hai, is liye jab paper poochay ke workbook me kitni sheets ho sakti hain to jawab hota hai jitni memory ijazat de."),
      LessonBlock.visual("Aik khula register jiske neeche warqon ke kinare tabs ki shakal me bahar nikle hon, aur un par Sheet1, Sheet2 aur January ka Hisab likha ho. Pure register ke gird aik ghaira bana kar Workbook likha ho aur aik warq ko alag rang me dikha kar Worksheet likha ho, taake poori file aur aik warq ka farq kabhi na bhoole."),
      LessonBlock.heading("Rows, Columns aur Cell"),
      LessonBlock.paragraph("Ab Excel ki asal buniyad par ate hain. Excel ki sheet khanon ka aik bohat bara jaal hai. Jo lakeerain left se right jaati hain, unhe row kehte hain. Row ko qatar bhi samajh lo, jese class me benchon ki qatrain. Rows ki pehchan numberon se hoti hai, sheet ke left kinare par 1, 2, 3, 4 likha hota hai. Aur jo lakeerain upar se neeche khari hain, unhe column kehte hain. Column ki pehchan angrezi hurf se hoti hai, upar A, B, C, D likha hota hai. Z, ke baad AA, AB shuru ho jata hai, bilkul wese hi jese 9 ke baad 10 ata hai."),
      LessonBlock.paragraph("Ab paper ke sab se mashhoor number suno, aur inhe pakka yaad kar lo. Aaj ke Excel me, yani 2007 ke baad wale har version me, aik worksheet me kul 1,048,576 rows hoti hain. Dus lakh se bhi zyada. Aur columns kul 16,384 hote hain. Aakhri column ka naam XFD hai. Yani sheet ka sab se aakhri khana, sab se aakhri cell, XFD1048576 hai. Ab purana wala hisaab bhi sun lo, kyunke paper dono poochta hai. Excel 2003 me sirf 65,536 rows aur sirf 256 columns hote thay, aur aakhri column IV hota tha. Purani kitabein aaj bhi yehi purane number deti hain, aur kabhi kabhi paper bhi purane number ko sahi option me rakhta hai jab sawal me 2003 ka zikr ho. Baghair version ke poocha jaye to hamesha naya number, 1,048,576 rows aur 16,384 columns, XFD."),
      LessonBlock.paragraph("Ab cell ki baat. Jahan aik row aur aik column apas me milte hain, wahan jo chhota sa khana banta hai, use cell kehte hain. Cell hi Excel ki sab se chhoti ikai hai, saara data cellon me hi likha jata hai. Har cell ka aik pata hota hai jise cell address kehte hain. Pata banane ka tareeqa ye hai ke pehle column ka harf, phir row ka number. Jese B4 ka matlab hai column B aur row number 4 wala khana. Bilkul ghar ke pate ki tarah, pehle gali ka naam, phir makaan number. Jis cell par tum is waqt kaam kar rahe hote ho, us ke gird kala sa mota ghaira ban jata hai, use active cell kehte hain. Aur do chhoti shortcuts bhi yaad kar lo jo paper me ati hain. Ctrl aur Home aik sath dabane se tum seedha A1 par pohnch jate ho, aur Ctrl aur End dabane se sheet ke us aakhri cell par jahan tak data likha gaya hai."),
      LessonBlock.visual("Excel ki grid ka aik bara hissa jisme aik row ko neele rang se aur aik column ko hare rang se numayan kiya gaya ho, aur jahan dono milte hain wahan cell B4 ko laal ghairay me dikhaya gaya ho. Sath me aik chhota sa khana jis me naya hisaab 1,048,576 rows, 16,384 columns, XFD, aur us ke neeche purana hisaab 65,536 rows, 256 columns, IV, taake dono number aik hi tasveer me yaad ho jayen."),
      LessonBlock.heading("Name Box aur Formula Bar"),
      LessonBlock.paragraph("Ribbon ke bilkul neeche, sheet ke upar wali patti par do cheezain hain jinhe students aksar nazar andaz kar dete hain, aur paper inhi ko poochta hai."),
      LessonBlock.paragraph("Left taraf chhota sa dabba hai, use Name Box kehte hain. Name Box tumhe batata hai ke is waqt tum khare kahan ho, yani active cell ka address wahan likha nazar ata hai, jese C7. Aur is ka dusra kaam ye hai ke agar tumhe kisi door ke cell par jana hai to Name Box me us ka address likh kar Enter daba do, tum seedha wahan pohnch jao ge. Naam rakha hua cell ya range ho to use bhi yahin se chuna jata hai."),
      LessonBlock.paragraph("Name Box ke sath lagi lambi patti Formula Bar hai. Formula Bar ka kaam ye hai ke ye active cell ke andar ki asal cheez dikhati hai. Ye farq samjho, ye bohat aham hai. Farz karo aik cell me tumhe 500 likha nazar araha hai. Ho sakta hai andar asal me 500 na ho, andar aik formula ho jis ka jawab 500 aya ho. Cell tumhe sirf jawab dikhata hai, lekin jab tum us cell ko chunte ho to Formula Bar me wo asal formula nazar ajata hai jo andar chhupa tha. Aur koi bhi data ya formula likhna ya theek karna ho to wo bhi yahin Formula Bar me hota hai. Formula Bar ke left kinare par chhota sa fx ka nishan hota hai, ye Insert Function ka button hai, is se functions ki list khulti hai. Paper me ye sawal ata hai ke cell ka asal content kahan nazar ata hai, jawab hai Formula Bar me."),
      LessonBlock.visual("Excel ki screen ke upari hisse ka bara sa manzar jis me Name Box ko aik teer se aur Formula Bar ko dusre teer se numayan kiya gaya ho. Aik cell me 500 ka jawab dikhaya gaya ho aur Formula Bar me usi ka asal formula bara bara likha nazar araha ho, taake cell jawab dikhata hai aur Formula Bar asal cheez, ye farq tasveer se pakka ho jaye."),
      LessonBlock.heading("Data ki teen types"),
      LessonBlock.paragraph("Excel ke cell me jo kuch likha jata hai wo buniyadi tor par teen qism ka hota hai, aur teeno ki pehchan paper me poochi jati hai."),
      LessonBlock.paragraph("Pehli qism text hai. Naam, sheher, cheezon ke label, jo kuch hisaab ke liye nahi sirf pehchan ke liye likha jaye, wo text hai. Text cell me default tor par left taraf chipka hota hai. Dusri qism number hai. Jo adad hisaab me istemal hona hai wo number hai, aur number cell me default tor par right taraf hota hai. Tareekh bhi andar se number hi hoti hai, is liye wo bhi right taraf jati hai. Teesri aur sab se aham qism formula hai. Formula wo hidayaat hai jo Excel ko batati hai ke hisaab kesay karna hai, aur formula ki pehchan ye hai ke ye hamesha barabar ke nishan yani = se shuru hota hai. = ke baghair Excel tumhari baat ko hisaab nahi samjhta, use aam text samajh kar beth jata hai. Jese =A1+A2 likho ge to Excel A1 aur A2 ki qeematein jama karke jawab cell me dikha dega."),
      LessonBlock.paragraph("Aik pehchan aur yaad kar lo jo paper ki pasandida hai. Jab formula ka hisaab mumkin na ho to Excel jawab ki jagah aik error dikhata hai. Sab se mashhoor error hai #DIV/0!, is ka matlab hai ke tum ne kisi number ko zero par taqseem karne ki koshish ki hai, jo hisaab me ho hi nahi sakta. Sharp wale nishan se shuru hone wala har error isi khandan ka hai."),
      LessonBlock.visual("Teen khane sath sath. Pehle me kisi ka naam likha left taraf chipka hua aur upar Text ka label, dusre me number right taraf aur upar Number ka label, teesre me = se shuru hone wala formula aur us ke neeche us ka jawab, upar Formula ka label. Neeche aik chhota khana jis me #DIV/0! laal rang me dikhaya gaya ho."),
      LessonBlock.heading("Mashhoor functions"),
      LessonBlock.paragraph("Function pehle se bane banaye formula ko kehte hain. Jese calculator par pehle se aik button bana hota hai jo dabane se ausat nikal ata hai, tumhe lamba hisaab nahi karna parta. Excel me sainkadon functions hain, lekin paper me chand hi bar bar ate hain. Inhe misaal ke sath samjho. Functions Formulas tab me milte hain, aur Home tab ke bilkul right kinare Editing group me AutoSum ka button bhi yahin ka rasta hai. AutoSum ki keyboard shortcut Alt aur = aik sath hai, ye bhi paper me ati hai."),
      LessonBlock.example("SUM. Jama karne ke liye. =SUM(A1:A5) likhne se A1 se A5 tak ke paanchon number jama ho jate hain. Beech wala : ka nishan \"se lekar tak\" ka matlab deta hai, ise range kehte hain."),
      LessonBlock.example("AVERAGE. Auzat nikalne ke liye. =AVERAGE(B1:B5) paanchon numberon ki ausat dega. Result card ki ausat yahin se banti hai."),
      LessonBlock.example("MAX. Sab se bari qeemat dhundne ke liye. =MAX(C1:C10) das numberon me sab se bara number dega, jese class me sab se zyada number kis ke aye."),
      LessonBlock.example("MIN. Sab se chhoti qeemat ke liye. =MIN(C1:C10) sab se chhota number dega."),
      LessonBlock.example("COUNT. Sirf number wale khane gin-ne ke liye. =COUNT(D1:D10) batayega ke das khanon me number kitno me hai. Khaas baat ye hai ke COUNT text wale khane nahi ginta. Agar text sameit har bhara khana ginna ho to us ke liye COUNTA istemal hota hai. COUNT aur COUNTA ka ye farq paper ka pasandida phanda hai."),
      LessonBlock.example("IF. Shart wala function. =IF(A1>=50,\"Pass\",\"Fail\") ka matlab hai ke agar A1 ki qeemat 50 ya zyada hai to jawab Pass likho, warna Fail likho. Ye function faisla karta hai, is liye result aur grade wale kaamon me sab se zyada yehi chalta hai."),
      LessonBlock.visual("Aik chhoti si marks wali sheet jis ke neeche har function ka aik khana bana ho, SUM ke aage jama ka jawab, AVERAGE ke aage ausat, MAX ke aage sab se bara number ghairay me, MIN ke aage sab se chhota, aur IF ke aage Pass ka label. Har function ke sath us ka asal formula Formula Bar wale andaaz me likha ho."),
      LessonBlock.heading("Cell Reference, relative aur absolute ka farq"),
      LessonBlock.paragraph("Ab aik bareek lekin bohat paper wala concept. Jab tum formula me kisi cell ka address likhte ho, jese =A1+B1, to is address ko cell reference kehte hain. Reference ki do baree qismein hain aur in ka farq sirf aik dollar ke nishan ka hai."),
      LessonBlock.paragraph("Pehli qism relative reference hai. Aam address jese A1. Is ki aadat ye hai ke jab tum formula ko copy karke dusri jagah le jate ho to ye address nayi jagah ke hisab se khud badal jata hai. Jese tum ne C1 me =A1+B1 likha aur use copy karke C2 me laga diya, to wahan wo khud =A2+B2 ban jayega. Ye asal me sahulat hai, isi liye poori list ka hisaab aik hi formula copy karke ho jata hai."),
      LessonBlock.paragraph("Dusri qism absolute reference hai. Is me column ya row ke aage dollar ka nishan \$ lagate hain, jese \$A\$1. Dollar ka matlab hai taala. Jis ke aage \$ lag gaya wo hissa copy karne par nahi badalta, wahi ka wahi rehta hai. Ye tab kaam ata hai jab aik fix qeemat, jese tax ki sharah ya aik fees, poori list par lagani ho aur tum chahte ho ke formula jahan bhi jaye, usi aik cell ko dekhta rahe. Aik teesri darmiyani shakal bhi hai jisme sirf column ya sirf row par taala lagta hai, use mixed reference kehte hain, jese \$A1 ya A\$1. Aur is ki shortcut bhi yaad kar lo, formula likhte waqt F4 dabane se reference relative se absolute aur absolute se relative ho jata hai. F4 wali ye baat paper me seedhi poochi jati hai."),
      LessonBlock.visual("Do raaste wali tasveer. Aik taraf aam address A1 jo copy hone par badal kar A2 banta dikhaya gaya ho, dusri taraf \$A\$1 jis par aik chhota sa taala bana ho aur copy hone ke baad bhi wo waisa ka waisa dikhaya gaya ho. Darmiyan me F4 wali kunji ka nishan."),
      LessonBlock.heading("Roz ke kaam aur un ke tabs"),
      LessonBlock.paragraph("Ab wo cheezain jo Excel me roz karni parti hain, aur paper me in ka sawal hamesha is shakal me ata hai ke falaan kaam kis tab se hota hai. Har kaam ke sath us ka tab zehen me jor lo."),
      LessonBlock.paragraph("Chart banana Insert tab ka kaam hai. Data select karo, Insert tab me Charts group se Column, Line ya Pie chart chuno, graph khud ban jata hai. Chart ki aik shortcut bhi hai, data select karke F11 dabane se chart alag sheet par ban jata hai. Data ko tartib dena yani sorting aur chhan-na yani filter lagana Data tab ka kaam hai, Sort and Filter group me. Filter ki shortcut Ctrl aur Shift aur L aik sath hai, is se har column ke upar chhota sa teer ajata hai jis se tum sirf matlooba cheezain dikha sakte ho. Bari sheet me pehli row ko rok lena taake neeche jane par headings ghayab na hon, ye Freeze Panes hai aur ye View tab ke Window group me milta hai. Sirf aik hisse ko print karna ho to pehle wo hissa select karke Page Layout tab ke Page Setup group me Print Area set karte hain. Do khano ko aik karna yani Merge and Center, Home tab ke Alignment group me hai, aur text ko khane ke andar lapaitna yani Wrap Text bhi yahi milta hai. Number ki shakal badalna, currency ka nishan ya feesad ka % lagana, ye Home tab ke Number group ka kaam hai."),
      LessonBlock.visual("Excel ke ribbon ka aik saaf naqsha jis me Insert, Data, View aur Page Layout tabs par un ke kaamon ki chhoti chhoti nishaniyan lagi hon, Insert par graph ki, Data par chhanni ki, View par barf se jami hui pehli row ki, aur Page Layout par print hone wale hisse ke gird ghairay ki. Student dekh kar hi yaad kar le ke konsa kaam kis tab me chhupa hai."),
      LessonBlock.heading("Zoom aur screen ka aakhri hissa"),
      LessonBlock.paragraph("Aakhri baat screen ke size ki. Sheet ko bara ya chhota karke dekhna zoom kehlata hai. Zoom do jagah se milta hai. Aik View tab ke Zoom group me, jahan tum feesad likh kar bhi zoom set kar sakte ho. Dusra aur asaan tareeqa screen ke bilkul neeche right kone me status bar par bana slider hai, use ghaseet kar zoom badlo. Excel me zoom kam se kam 10 feesad aur zyada se zyada 400 feesad hota hai. Ye 10 se 400 wali hadd bhi fix fact hai. Mouse ke sath Ctrl daba kar wheel ghumane se bhi zoom badalta hai."),
      LessonBlock.visual("Screen ke neeche wali status bar ka bara manzar jis me right kone ka zoom slider numayan ho, aik taraf 10 feesad par chhoti si sheet aur dusri taraf 400 feesad par aik hi cell bohat bara dikhaya gaya ho."),
      LessonBlock.heading("Fix facts ki recap"),
      LessonBlock.paragraph("Ab aakhir me wo tamam fix facts aik sath dohra lo jo is overview se paper ke liye nikalte hain. Inhe bol bol kar yaad karo."),
      LessonBlock.example("Nayi Excel file ka default naam Book1 hota hai."),
      LessonBlock.example("Excel ki nayi extension .xlsx hai, purani .xls thi, farq 2007 ka hai."),
      LessonBlock.example("Workbook poori file hai, worksheet us ka aik warq hai."),
      LessonBlock.example("Nayi workbook me default aik sheet hoti hai, purane Excel me teen hoti thi."),
      LessonBlock.example("Sheet ke naam ki hadd 31 characters hai."),
      LessonBlock.example("Naye Excel me rows 1,048,576 aur columns 16,384 hain, aakhri column XFD hai aur aakhri cell XFD1048576 hai."),
      LessonBlock.example("Purane Excel 2003 me rows 65,536 aur columns 256 thay, aakhri column IV tha."),
      LessonBlock.example("Cell row aur column ke milap ko kehte hain, address pehle column ka harf phir row ka number hota hai, jese B4."),
      LessonBlock.example("Name Box active cell ka address dikhata hai, Formula Bar cell ka asal content aur formula dikhati hai."),
      LessonBlock.example("Formula hamesha = se shuru hota hai."),
      LessonBlock.example("SUM jama karta hai, AVERAGE ausat, MAX sab se bara, MIN sab se chhota, COUNT sirf number wale khane ginta hai, COUNTA har bhara khana, IF shart par faisla karta hai."),
      LessonBlock.example("Absolute reference me \$ ka nishan lagta hai, aur F4 se reference badalta hai."),
      LessonBlock.example("Chart Insert tab se banta hai, sort aur filter Data tab se, Freeze Panes View tab se, Print Area Page Layout tab se."),
      LessonBlock.example("Default font Calibri aur size 11 hai."),
      LessonBlock.example("Zoom 10 feesad se 400 feesad tak hota hai."),
      LessonBlock.heading("Yaad rakhne ki trick"),
      LessonBlock.paragraph("Aakhir me aik trick jo numberon ko zehen me baitha degi. Naye Excel ke number is jumle me bandh lo. Rows das lakh se upar, columns solah hazar se upar, aur safar XFD par khatam. Das lakh wali baat 1,048,576 ko, solah hazar wali baat 16,384 ko yaad karayegi, aur XFD sunte hi aakhri column zehen me ajayega. Aur purane ke liye ulta jumla rakho. Purana Excel chhota tha, 65 hazar rows aur 256 columns, safar IV par khatam. Naya bara, purana chhota. Version dekh kar number chuno, ghalti nahi hogi."),
    ],
  ),
  GeoTopic(
    id: "ms-powerpoint",
    title: "MS PowerPoint ka Complete Overview",
    subtitle: "PowerPoint. Stage par dikhane wali slides, aur paper ke fix facts",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye overview kyun zaroori hai"),
      LessonBlock.paragraph("PPSC ke one paper me computer ke hisse me MS PowerPoint par bhi sawal ate hain, aur PowerPoint ke sawal Excel se bhi zyada fix hote hain. Slideshow kis key se shuru hota hai, nayi file ki extension kya hai, default view konsa hai, transition aur animation me kya farq hai. Ye sawal samajh se zyada pehchan mangte hain. Jo student is overview ko aik dafa screen ki tasveer zehen me bana kar parh le, us ke liye ye sawal muft ke number hain. Har cheez pehle samjhai jayegi, phir bataya jayega ke PowerPoint ki screen par wo milti kahan hai, aur phir wo fix fact milega jo paper me seedha poocha jata hai."),
      LessonBlock.heading("Pehle PowerPoint ko samajh lo"),
      LessonBlock.paragraph("Dekho, sab se pehle PowerPoint ko samajh lo. Farz karo tumhe class ke samne aik mozू par bolna hai. Tum board par sab kuch nahi likh sakte, to tum bare bare kagaz ke takhte bana lete ho. Har takhte par aik bara unwan, chand aham nuqaat, aur aik tasveer. Bolte hue tum takhte badalte jate ho aur log dekhte bhi jate hain, sunte bhi jate hain. PowerPoint bas inhi takhton ki electronic shakal hai."),
      LessonBlock.paragraph("PowerPoint Microsoft Office ka wo program hai jo presentation banane ke liye hai. Presentation ka matlab hai slides ka wo majmua jo screen ya projector par dikha kar kisi mozू ko samjhaya jaye. Har takhte ko yahan slide kehte hain. Daftar ki report ho, school ka lecture ho, kisi nai cheez ki mashhoori ho, jahan baat ko bare unwanon, tasveeron aur charton ke sath dikhana ho, wahan PowerPoint kaam ata hai. Word me likhte hain, Excel me gin-te hain, aur PowerPoint me dikhate hain. Ye teeno jumle aik sath zehen me rakho, teeno programs ka farq kabhi nahi bhoologe."),
      LessonBlock.visual("Aik stage ka manzar jis me bolne wale ke peeche bari screen par slides badal rahi hon, aur sath me kagaz ke takhton wala purana andaaz chhota sa dikhaya gaya ho. Har takhte aur har slide par aik hi unwan aur aik hi tasveer ho, taake student samajh jaye ke slide asal me stage wala takhta hi hai."),
      LessonBlock.heading("File ki pehchan, extension aur default naam"),
      LessonBlock.paragraph("Jab tum nayi PowerPoint file kholte ho to upar us ka naam Presentation1 likha ata hai. Presentation1 har nayi khali presentation ka default naam hai, bilkul wese hi jese Excel me Book1 hota hai. Ye baat paper me poochi jati hai, isay fix fact samajh kar yaad rakho."),
      LessonBlock.paragraph("Extension ki baat wohi hai jo Excel me seekhi. Extension file ke khandan ka naam hai. PowerPoint 2003 aur us se pehle ke zamane me file ki extension .ppt hoti thi. 2007 me naya format aya aur extension .pptx ho gayi. Aaj ke PowerPoint 2016 aur Microsoft 365 me default extension .pptx hai, aur baghair version ke pooche gaye sawal ka jawab .pptx hi banta hai. Version wala usool yahan bhi wohi hai, 2007 se pehle .ppt, 2007 ke baad .pptx. Aik aur extension bhi zehen me rakho jo kabhi kabhi paper me ati hai. Agar presentation ko .ppsx me save karo to wo show wali file ban jati hai, use kholte hi seedha slideshow shuru ho jata hai, pehle editing wali screen nahi ati."),
      LessonBlock.visual("Teen file icon aik line me. Pehle par Presentation1 ka default naam, dusre par purana .ppt 2003 ke label ke sath, teesre par naya .pptx 2007 ke baad ke label ke sath. Aik chhota chautha icon .ppsx ka jis se seedha bari screen wali slide nikalti dikhai de."),
      LessonBlock.heading("Slide, Layout aur Placeholder"),
      LessonBlock.paragraph("Ab presentation ki teen buniyadi cheezain samjho, kyunke paper inhi teenon ke gird ghoomta hai."),
      LessonBlock.paragraph("Pehli cheez slide hai. Slide presentation ka aik safha hai, aik screen bhar ka hissa. Poori presentation slides ka majmua hai, jese kitaab safhon ka majmua hoti hai. Aik slide par unwan hota hai, nuqaat hote hain, tasveer ya chart hota hai."),
      LessonBlock.paragraph("Dusri cheez layout hai. Layout slide ke andar cheezon ki tartib ko kehte hain, kis cheez ki jagah kahan hogi. PowerPoint me pehle se bane banaye layouts hote hain, kul 9 mashhoor layouts hain. Sab se pehla Title Slide hai, is me sirf bara unwan aur us ke neeche chhota unwan hota hai, aur har nayi presentation ki pehli slide ka default layout yehi Title Slide hota hai, ye fix fact hai. Dusra sab se zyada istemal hone wala Title and Content hai, upar unwan aur neeche nuqaat ya koi bhi cheez. Is ke ilawa Title Only hai jis me sirf unwan hota hai, Blank hai jo bilkul khali slide hai, aur Two Content, Section Header, Content with Caption jese layouts bhi hain. Nayi slide jorna Home tab ke Slides group me New Slide se hota hai, is ki shortcut Ctrl aur M hai, aur bani hui slide ka layout badalna ho to usi group me Layout ka button hai."),
      LessonBlock.paragraph("Teesri cheez placeholder hai. Slide par jo khali dabbe nazar ate hain jin ke andar halki si tehreer likhi hoti hai, Click to add title ya Click to add text, unhe placeholder kehte hain. Placeholder ka matlab hai pehle se tay jagah, tum bas wahan click karke apni cheez likh do ya laga do. Ye dabbe batate hain ke unwan yahan aye ga, text yahan aye ga, tasveer yahan lage gi. Paper me placeholder ki tareef is shakal me ati hai ke slide par wo dabba jahan click karke text likha jata hai, use kya kehte hain. Jawab placeholder hai."),
      LessonBlock.visual("Aik slide ka bara manzar jis me upar wale dabbe par Title wala placeholder aur neeche wale par Text wala placeholder teeron se dikhaya gaya ho, aur dono ke andar Click to add wali halki tehreer nazar arahi ho. Sath me teen chhoti slides, Title Slide, Title and Content aur Blank, taake layouts ka farq aik nazar me samajh aye."),
      LessonBlock.heading("Default view, Normal aur baqi views"),
      LessonBlock.paragraph("Jab tum PowerPoint kholte ho to jo screen samne ati hai use Normal view kehte hain, aur yehi PowerPoint ka default view hai. Ye fix fact paper me bar bar ata hai. Normal view ke teen hisse hote hain aur teeno ko pehchan lo. Left taraf aik tung si patti hai jis me tamam slides chhoti chhoti shaklon me nazar ati hain, ise Slides pane kehte hain, yahan se tum kisi bhi slide par aik click me ja sakte ho. Darmiyan me bari jagah hai jahan mojooda slide bara dikhai deta hai, yahi asal kaam ki jagah hai. Aur neeche aik chhoti si patti hai jahan tum us slide ke notes likh sakte ho, notes wali baat aage tafseel se ayegi."),
      LessonBlock.paragraph("Views sirf Normal nahi hain. View tab ke Presentation Views group me saare views milte hain. Slide Sorter view me tamam slides chhoti shaklon me aik sath nazar ati hain, ye slides ki tartib badalne aur aik nazar me poori presentation dekhne ke liye sab se behtreen hai. Outline View me sirf unwan aur nuqaat tehreer ki shakal me ate hain. Reading View me presentation window ke andar chalti hai lekin editing wale button ghayab ho jate hain. Paper me aksar poocha jata hai ke slides ko chhoti shaklon me aik sath dekhne ke liye konsa view hai, jawab Slide Sorter hai. Aur default view poocha jaye to jawab hamesha Normal hai."),
      LessonBlock.visual("Normal view ki poori screen ka naqsha jis me left wali Slides pane, darmiyan wali bari slide aur neeche wali notes patti, teeno par un ke naam ke label lage hon. Neeche aik chhoti patti me Slide Sorter ka manzar jisme bohat si chhoti slides aik sath dikhai de rahi hon."),
      LessonBlock.heading("Tabs ka khulasa"),
      LessonBlock.paragraph("Ab ribbon ke bare tabs ka aik khulasa zehen me rakho, taake har kaam ki jagah yaad rahe."),
      LessonBlock.paragraph("Home tab sab se zyada istemal hota hai. Isi me Slides group hai jahan se New Slide, Layout aur Reset milta hai, isi me Font aur Paragraph groups hain jahan se likhai ka size, rang aur tartib badalti hai. Insert tab se slide ke andar cheezain jori jati hain, tasveer, table, chart, shapes aur video waghera. Design tab poori presentation ki shakal ka tab hai, isi me Themes milte hain jin se aik click me tamam slides ka rang, font aur andaaz badal jata hai, aur isi tab me aage ayegi slide size wali baat. Is ke baad Transitions aur Animations tabs hain jin ka farq agle hisse me tafseel se ayega kyunke paper ka sab se bara phanda wahi hai. Slide Show tab se show ki settings hoti hain, aur View tab se views aur master slide milta hai."),
      LessonBlock.visual("PowerPoint ke ribbon ka saaf naqsha jis me Home, Insert aur Design tabs par un ki pehchan wali chhoti nishaniyan lagi hon, Home par slide ki, Insert par tasveer ki, Design par rangon ki pallete ki. Har tab ke neeche aik line me us ka kaam."),
      LessonBlock.heading("Transitions aur Animations ka farq"),
      LessonBlock.paragraph("Ab is overview ka sab se aham hissa, kyunke PPSC ka paper yahin sab se zyada phansata hai. Transition aur animation sunne me aik jaise lagte hain, dono me harkat hai, lekin dono ka maqam bilkul alag hai. Is farq ko aik misaal se pakka kar lo."),
      LessonBlock.paragraph("Farz karo tum aik theatre me bethe ho. Aik manzar khatam hota hai aur parda girta hai, phir parda uthta hai aur naya manzar samne ata hai. Parda girne aur uthne ka ye andaaz transition hai. Aur manzar ke andar jo adakar chal raha hai, nach raha hai, uchhal raha hai, wo animation hai. Bas yehi farq hai. Transition slide badalne par lagta hai, animation slide ke andar ki cheezon par lagta hai."),
      LessonBlock.paragraph("Tafseel se samjho. Transition aik slide ke khatam hone aur dusri slide ke ane ke darmiyan ka effect hai. Ye poori slide par aik sath lagta hai. Ise lagane ke liye Transitions tab me jate hain. Mashhoor transitions me Fade hai jis me slide halki si ghul kar ati hai, Push hai jis me nai slide purani ko dhakel kar ati hai, Wipe hai, aur naya mashhoor Morph hai jo PowerPoint 2019 aur 365 me aya aur aik slide ki cheez ko dusri slide me narmi se badal deta hai. Jab kisi slide par transition lag jaye to Slides pane me us slide ke neeche aik chhota sa sitara ban jata hai."),
      LessonBlock.paragraph("Animation slide ke andar rakhi cheez ki harkat hai. Aik unwan ka urh kar ana, aik nuqte ka aik aik karke zahir hona, tasveer ka ghoomna, ye sab animation hai. Ise lagane ke liye pehle wo cheez select karte hain, phir Animations tab me jate hain. Animations ki baree qism hai entrance, yani cheez ka andar ana, jese Appear, Fade aur Fly In. Is ke ilawa cheez ko numayan karne wale emphasis effects aur bahar nikalne wale exit effects bhi hote hain. Lagi hui animations ki list aur un ki tartib dekhne ke liye Animations tab me Animation Pane kholte hain."),
      LessonBlock.paragraph("Aik line me farq bandh lo. Transition darwaze ke khulne ka andaaz hai, animation kamre ke andar ki harkat hai. Sawal me agar poocha jaye ke aik slide se dusri slide par jane ka effect kya kehlata hai to jawab transition, aur agar poocha jaye ke slide par mojood text ko urh kar lane ka effect kya hai to jawab animation. Yehi do sawal har dusre paper me ate hain."),
      LessonBlock.visual("Do hisso wali tasveer. Aik taraf theatre ka parda girta aur uthta dikhaya gaya ho aur upar Transition likha ho, sath me do slides ke darmiyan teer bana ho. Dusri taraf aik hi slide ke andar unwan urh kar ata dikhaya gaya ho aur upar Animation likha ho. Darmiyan me aik bari lakeer aur us par likha ho, transition slide badalne par, animation slide ke andar."),
      LessonBlock.heading("Slideshow chalana"),
      LessonBlock.paragraph("Presentation banane ka asal maqsad use chalana hai, aur chalane ke tareeqe paper ke sab se fix sawal hain."),
      LessonBlock.paragraph("Slideshow shuru karne ki sab se mashhoor key F5 hai. F5 dabane se show hamesha pehli slide se shuru hota hai. Agar tum beech ki kisi slide se show shuru karna chahte ho, to pehle wo slide select karo aur Shift aur F5 aik sath dabao, show usi mojooda slide se shuru ho jayega. Ye F5 aur Shift F5 ka jora paper me lazmi ata hai, inhe jor kar yaad rakho. Show khatam karne ke liye Esc dabate hain. Show ke doran agli slide par jane ke liye right wala teer, Space ya Enter chalta hai, aur pichli slide par wapas jane ke liye left wala teer ya Backspace. Do aur chhoti keys bhi yaad kar lo jo paper me ati hain. Show ke doran B dabane se screen bilkul kaali ho jati hai, taake logon ki tawajjo screen se hat kar tum par aye, aur W dabane se screen safed ho jati hai. Dobara wohi key dabane se slide wapas ajati hai. Slide Show tab me From Beginning ka button bhi wohi kaam karta hai jo F5 karta hai, aur From Current Slide ka button wohi jo Shift F5 karta hai."),
      LessonBlock.visual("Aik keyboard ka hissa jis me F5 wali key hare rang me aur Shift aur F5 ka jora neele rang me numayan ho, sath me Esc wali key laal rang me. Har key ke neeche aik line me us ka kaam, F5 pehli slide se, Shift F5 mojooda slide se, Esc khatam."),
      LessonBlock.heading("Slide ka size, 4:3 aur 16:9"),
      LessonBlock.paragraph("Aik aur fix fact jo zamane ke sath badla hai, aur paper dono zamane poochta hai. Purane zamane me slides ka size 4:3 hota tha. Ise standard size kehte thay, is ki lambai 10 inch aur chorai 7.5 inch hoti thi, aur ye purane motay monitoron aur projectoron ki shakal thi. Phir chaudi screenon ka zamana aya. PowerPoint 2013 se default slide size 16:9 ho gaya, jise widescreen kehte hain. Is ki lambai 13.33 inch aur chorai wohi 7.5 inch hai. Aaj ke TV, laptop aur projector sab 16:9 hain, is liye nai presentation kholte hi slide chaudi ati hai. Slide ka size badalna ho to Design tab ke Customize group me Slide Size ka button hai, wahan se 4:3 aur 16:9 me se chun sakte ho. Paper me baghair version ke poocha jaye to jawab 16:9 hai, aur purane PowerPoint ka poocha jaye to 4:3."),
      LessonBlock.visual("Do slides sath sath khari hon. Aik tung aur unchi si jis par 4:3 aur purana zamana likha ho, dusri chaudi jis par 16:9 aur naya default likha ho. Dono ke neeche un ki inch wali paimaish, taake shakal dekh kar hi size yaad ho jaye."),
      LessonBlock.heading("Notes aur Handouts"),
      LessonBlock.paragraph("Ab do cheezain jo dikhai nahi detin lekin paper me lazmi ati hain."),
      LessonBlock.paragraph("Pehli hai notes. Har slide ke neeche jo chhoti si jagah hoti hai, wahan bolne wala apne liye notes likhta hai. Ye notes wohi baatein hoti hain jo tumhe bolte waqt yaad rakhni hain lekin screen par dikhana nahi chahte. Khaas baat ye hai ke ye notes audience ko nazar nahi ate. Jab tum Presenter View me show chalate ho to tumhari apni screen par slide ke sath notes bhi dikhte hain, lekin projector par sirf slide jati hai. Notes alag safhe ki shakal me dekhne ke liye View tab me Notes Page view bhi hai. Paper me poocha jata hai ke speaker ke notes kahan likhe jate hain, jawab hai slide ke neeche wale Notes pane me."),
      LessonBlock.paragraph("Dusri hai handouts. Handout wo print hai jo tum sunne walon ko dete ho taake wo presentation ka khulasa apne pas rakh lein. Print karte waqt File tab me Print me jao, wahan Full Page Slides wali setting ki jagah Handouts chun lo. Aik safhe par 1, 2, 3, 4, 6 ya 9 slides print ho sakti hain. In me sab se khaas 3 slides wala handout hai, kyunke us me har slide ke sath khali lakeerain bani hoti hain jin par sunne wale apne notes likh sakte hain. Ye 3 wali khaasiyat paper ka pasandida sawal hai."),
      LessonBlock.visual("Aik taraf presenter ki screen jis par slide ke sath us ke notes bhi dikhai de rahe hon, aur usi ke sath projector wali screen jis par sirf slide ho. Dusri taraf aik chhapa hua safha jis par teen chhoti slides aur har aik ke sath khali lakeerain hon, upar Handout likha ho."),
      LessonBlock.heading("Master Slide"),
      LessonBlock.paragraph("Ab wo taqatwar cheez jo bare kaam ko aik click me kar deti hai. Farz karo tumhari presentation me 40 slides hain aur tum chahte ho ke har slide par company ka logo upar wale kone me aye, har unwan ka rang aik jaisa ho aur neeche har slide par tumhara naam likha aye. Agar tum ye kaam 40 slides par alag alag karo ge to aadha din lag jayega. Master slide is ka hal hai."),
      LessonBlock.paragraph("Slide Master View tab ke Master Views group me milta hai. Master slide sab slides ki maan hai. Jo tabdeeli tum master par kar do, wo tamam slides par khud lag jati hai. Master par logo laga do to har slide par logo ajayega, master par unwan ka font badal do to har slide ka unwan badal jayega. Kaam khatam karke Close Master View se wapas aate hain. Paper me sawal is shakal me ata hai ke tamam slides par aik sath tabdeeli karne ke liye kya istemal hota hai, jawab Slide Master hai. Aur ye bhi yaad rakho ke master sirf shakal badalta hai, har slide ka apna text waisa ka waisa rehta hai."),
      LessonBlock.visual("Aik bari master slide upar aur us ke neeche us se juri hui bohat si chhoti slides, jese aik darakht aur us ki shakhein. Master slide par logo aur neela unwan dikhaya gaya ho aur tamam chhoti slides par wohi logo aur wohi neela unwan nazar araha ho."),
      LessonBlock.heading("Rehearse Timings"),
      LessonBlock.paragraph("Aakhri kaam ki cheez rehearsal hai. Kabhi presentation ko khud bakhud chalana hota hai, jese kisi numaish me lagi screen par slides khud badalti rahen aur koi bolne wala na ho. Is ke liye pehle waqt ki mashq karte hain. Slide Show tab ke Set Up group me Rehearse Timings ka button hai. Use chalane se show shuru ho jata hai aur PowerPoint har slide par tumhara guzra hua waqt record karta rehta hai. Mashq khatam hone par wo waqton ko save kar lene ko kehta hai. Us ke baad show unhi waqton par khud chalti hai, har slide utni hi der rukti hai jitni der tum ne mashq me rukay thay. Paper me poocha jata hai ke har slide ka waqt pehle se set karne ke liye konsa option hai, jawab Rehearse Timings hai."),
      LessonBlock.visual("Aik slide ke upar bari si stopwatch bani ho aur neeche teen slides aik line me jin ke neeche un ke waqt likhe hon, 10 second, 15 second, 10 second, aur teer dikhata ho ke show khud age barh rahi hai baghair kisi ke dabaye."),
      LessonBlock.heading("Fix facts ki recap"),
      LessonBlock.paragraph("Ab aakhir me wo tamam fix facts aik sath dohra lo jo is overview se paper ke liye nikalte hain."),
      LessonBlock.example("Nayi presentation ka default naam Presentation1 hota hai."),
      LessonBlock.example("PowerPoint ki nayi extension .pptx hai, purani .ppt thi, farq 2007 ka hai. Show wali file .ppsx hoti hai."),
      LessonBlock.example("Presentation slides ka majmua hai, aur pehli slide ka default layout Title Slide hai."),
      LessonBlock.example("Layout slide par cheezon ki tartib hai, mashhoor layouts kul 9 hain, nayi slide ki shortcut Ctrl aur M hai."),
      LessonBlock.example("Placeholder slide par wo pehle se tay dabba hai jahan click karke text likha jata hai."),
      LessonBlock.example("PowerPoint ka default view Normal hai, aur slides ko chhoti shaklon me aik sath dekhne ka view Slide Sorter hai."),
      LessonBlock.example("Transition slide badalne par lagta hai aur Transitions tab me milta hai, animation slide ke andar ki cheez par lagta hai aur Animations tab me milta hai."),
      LessonBlock.example("Slideshow F5 se pehli slide se shuru hota hai, Shift aur F5 se mojooda slide se, aur Esc se khatam hota hai."),
      LessonBlock.example("Naya default slide size 16:9 widescreen hai, purana size 4:3 tha."),
      LessonBlock.example("Speaker notes slide ke neeche Notes pane me likhe jate hain aur audience ko nazar nahi ate."),
      LessonBlock.example("Aik safhe par 3 slides wale handout me notes likhne ki lakeerain hoti hain."),
      LessonBlock.example("Tamam slides par aik sath tabdeeli Slide Master se hoti hai jo View tab me hai."),
      LessonBlock.example("Har slide ka waqt pehle se set karna Rehearse Timings hai jo Slide Show tab me hai."),
      LessonBlock.heading("Yaad rakhne ki trick"),
      LessonBlock.paragraph("Aakhir me do chhoti tricks jo do sab se bare sawalon ko hamesha ke liye pakka kar dein gi. Pehli slideshow wali. F5 ko Full Five samjho, full show pehli slide se. Aur Shift F5 ko yun yaad rakho ke Shift matlab yahin se, mojooda slide se. Dusri trick transition aur animation wali hai. Jab bhi shak ho to theatre wala parda yaad karo. Parda yani transition, ye slide badalne par ata hai. Adakar yani animation, ye slide ke andar harkat karta hai. Parda bahar, adakar andar. Bas, farq kabhi nahi bhoologe."),
    ],
  ),
  GeoTopic(
    id: "shortcuts",
    title: "Computer Course: Shortcut Keys ka Course",
    subtitle: "Ctrl wale shortcuts, F1 se F12 tak function keys, aur Windows wale shortcuts",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye course kyun zaroori hai"),
      LessonBlock.paragraph("One paper me shortcut keys ke sawal har saal ate hain, aur ye sawal un students ke liye muft ke number hote hain jinhon ne keys ko samajh kar yaad kiya ho. Ctrl+S kis kaam ka hai, F7 dabane se kya hota hai, Excel me F2 ka kya kaam hai — ye chhote chhote sawal hain lekin paper me yahi asli farq dalte hain, kyunke zyada tar students inhein parhe baghair ajate hain. Shortcut ka matlab hai mouse ghumane ke bajaye keyboard ki do teen keys aik sath daba kar kaam kar lena. Is course me hum keys ko teen hisson me parhen ge. Pehle Ctrl wale shortcuts jo har jagah chalte hain, phir F1 se F12 tak ki function keys jin ka har aik ka apna khaas kaam hai, aur aakhir me Alt aur Windows wale shortcuts. Har key ke sath ye bhi bataunga ke wo kis app me sab se zyada poochi jati hai, taake paper me sawal dekhte hi jawab zehen me ajaye."),
      LessonBlock.heading("Pehla hissa: Ctrl wale shortcuts"),
      LessonBlock.paragraph("Ctrl key keyboard ke neeche dono taraf hoti hai, aur kisi dusri key ke sath mil kar ye jadoo karti hai. In shortcuts ki khaasiyat ye hai ke ye taqreeban har program me aik hi kaam karte hain, Word ho ya Excel ya browser. Main board par tartib se likh raha hun, har key ke sath us ka kaam samjho."),
      LessonBlock.example("Ctrl+A ka matlab Select All hai. Poori file ka sara text ya sari cheezein aik sath chun li jati hain. Word aur Excel dono me ye bohat poocha jata hai."),
      LessonBlock.example("Ctrl+B text ko Bold karta hai, yani mota aur gehra. MS Word ka sab se mashhoor sawal yahi hai."),
      LessonBlock.example("Ctrl+I text ko Italic karta hai, yani terha jhuka hua. B ke baad I hi ata hai paper me."),
      LessonBlock.example("Ctrl+U text ke neeche line lagata hai, yani Underline. Ye teeno, B, I aur U, hamesha aik sath yaad rakho."),
      LessonBlock.example("Ctrl+C ka matlab Copy hai. Chuni hui cheez ki naqal bana kar yaad rakh li jati hai, asal cheez apni jagah rehti hai."),
      LessonBlock.example("Ctrl+X ka matlab Cut hai. Cheez apni jagah se kat kar chali jati hai. Copy aur Cut ka farq paper me bohat ata hai. Copy me asal rehta hai, Cut me asal bhi uth jata hai."),
      LessonBlock.example("Ctrl+V ka matlab Paste hai. Copy ya Cut ki hui cheez ko nayi jagah par chipka deta hai. Yaad rakhne ki baat ye hai ke Paste ke liye P nahi, V hai, kyunke P pehle hi Print ke liye makhsoos hai."),
      LessonBlock.example("Ctrl+Z ka matlab Undo hai. Jo aakhri kaam kiya tha, use wapas le leta hai. Ghalti ho jaye to ye sab se pehle dabane wali key hai."),
      LessonBlock.example("Ctrl+Y ka matlab Redo hai. Jo kaam Undo se wapas liya tha, use dobara kar deta hai. Z aur Y ko jora samajh kar yaad rakho, aik wapas, dusra dobara."),
      LessonBlock.example("Ctrl+S ka matlab Save hai. File ko mehfooz kar lena. Ye one paper ka sab se zyada dohraaya jane wala sawal hai, har haal me pakka hona chahiye."),
      LessonBlock.example("Ctrl+P ka matlab Print hai. File ko printer se chhapne ka hukum."),
      LessonBlock.example("Ctrl+N nayi file banata hai, yani New. Word me nayi khaali document aur browser me nayi window khulti hai."),
      LessonBlock.example("Ctrl+O pehle se bani hui file kholta hai, yani Open."),
      LessonBlock.example("Ctrl+F ka matlab Find hai. Bari file me koi lafz dhundna ho to yahi dabate hain. Browser me bhi page ke andar lafz isi se milta hai."),
      LessonBlock.example("Ctrl+H ka matlab Replace hai. Aik lafz ko dhund kar us ki jagah dusra lafz rakh deta hai. Word me ye Find ka bara bhai hai aur paper me aksar F ke sath mila kar poocha jata hai."),
      LessonBlock.example("Ctrl+K hyperlink lagata hai. Word aur PowerPoint me kisi lafz ko kisi website se jorne ke liye yehi key hai."),
      LessonBlock.example("Ctrl+L text ko left side par kar deta hai, Ctrl+E darmiyan yani center me lata hai, Ctrl+R right side par kar deta hai, aur Ctrl+J text ko dono taraf se barabar kar deta hai jise Justify kehte hain, akhbaar ke column ki tarah. Ye chaaron alignment wale shortcuts sirf Word me kaam karte hain aur paper me in ka jora bohat ata hai. E ko Center se jor kar yaad rakho, kyunke C pehle hi Copy ke pas hai."),
      LessonBlock.example("Ctrl+Enter Word me page break dalta hai, yani likhai usi jagah se naye page par chali jati hai. Bar bar Enter dabane ke bajaye ye aik key kaafi hai."),
      LessonBlock.example("Ctrl+Shift+barra wala nishan, yani greater than wali key, Word me chune hue text ka font size bara karti hai, aur Ctrl+Shift+chhota wala nishan font size chhota karta hai. Font size wale sawal me ye jora ata hai."),
      LessonBlock.example("Ctrl+Home file ke bilkul shuru me le jata hai aur Ctrl+End file ke bilkul aakhir me. Ye do bhi Word me aksar pooche jate hain."),
      LessonBlock.heading("Dusra hissa: F1 se F12 tak function keys"),
      LessonBlock.paragraph("Keyboard ki sab se upar wali line me F1 se F12 tak ki keys hoti hain, inhein function keys kehte hain. In ka masla ye hai ke har key ka kaam alag hai, aur kuch keys ka kaam alag alag program me badal bhi jata hai. Paper yahi par phasata hai, is liye har key ko us ke mashhoor kaam ke sath yaad karo."),
      LessonBlock.example("F1 har program me Help ki key hai. Kahin phans jao to F1 dabao, madad wali screen khul jati hai. Ye sab se asaan aur sab se zyada poocha jane wala sawal hai."),
      LessonBlock.example("F2 ke do mashhoor kaam hain. Windows me kisi file ya folder ka naam badalne yani Rename ke liye F2 dabate hain. Aur Excel me F2 dabane se cell ke andar likha hua badla ja sakta hai, yani cell edit hota hai. Paper me F2 aksar Excel ke hawale se ata hai."),
      LessonBlock.example("F3 Windows me search aur Find ke kaam ati hai, aur Word me kuch jagah text dhundne me madad karti hai. Ye baqi keys ke muqable me kam poochi jati hai."),
      LessonBlock.example("F4 ka apna seedha kaam pichle action ko dohrana hai, khaas tor par Word aur Excel me. Lekin is ki asal shohrat Alt ke sath hai. Alt+F4 dabane se jo program khula ho wo band ho jata hai, aur desktop par hon to computer band karne wali screen ati hai. Paper me F4 ka sawal taqreeban hamesha Alt+F4 ki shakal me ata hai."),
      LessonBlock.example("F5 ke do bare kaam hain aur yahi is ka jaal hai. Browser aur Windows me F5 ka matlab Refresh hai, page dobara load ho jata hai. Lekin PowerPoint me F5 dabane se slideshow shuru se shuru ho jata hai. Paper me jab F5 PowerPoint ke sath aye to jawab slideshow hai, aur browser ke sath aye to refresh hai. Sawal ko gaur se parhna, yahi is key ka asal imtihan hai."),
      LessonBlock.example("F6 aik hisse se dusre hisse me jane ke kaam ati hai, jese browser me address bar par jana. Ye bohat kam poochi jati hai, bas pehchan ke tor par yaad rakho."),
      LessonBlock.example("F7 MS Word aur baqi Office programs me spelling aur grammar ki ghaltiyan check karti hai. Ye one paper ka fix sawal hai. Spelling check wali key poochi jaye to jawab hamesha F7 hai."),
      LessonBlock.example("F8 ke bhi do roop hain. Computer start hote waqt F8 dabane se Safe Mode khulta hai, ye Windows wala purana aur mashhoor sawal hai. Word aur Excel me F8 selection ko barhane ke kaam bhi ata hai, lekin paper me Safe Mode wala matlab hi ata hai."),
      LessonBlock.example("F9 Excel me tamam formulas ko dobara calculate karti hai. Word me ye fields ko update karti hai. Excel ke paper sawal me F9 ka yahi hisaab wala kaam ata hai."),
      LessonBlock.example("F10 program ki menu bar ko active karti hai, yani upar wale menu khulne ke liye tayyar ho jate hain. Ye bhi kam poochi jati hai."),
      LessonBlock.example("F11 ke do kaam yaad rakho. Browser me F11 dabane se full screen ho jati hai, upar neeche ki pattiyan ghayab ho jati hain. Aur Excel me F11 dabane se chune hue data ka chart aik alag nayi sheet par ban jata hai. Paper me F11 Excel ke chart wale kaam ke sath mashhoor hai."),
      LessonBlock.example("F12 MS Office me Save As kholti hai, yani file ko naye naam ya nayi jagah par save karna. Gaur karo, Ctrl+S seedha save karta hai aur F12 Save As kholti hai. Ye farq paper me bohat pyar se poocha jata hai."),
      LessonBlock.heading("Teesra hissa: Alt aur Windows wale shortcuts"),
      LessonBlock.paragraph("Ab wo shortcuts jo pure computer ko chalane me kaam ate hain, kisi aik program ke nahi. Ye Windows wale sawal hain aur one paper me in ka apna hissa hota hai."),
      LessonBlock.example("Alt+Tab khule hue programs ke darmiyan switch karti hai. Do teen program khule hon to mouse ke baghair un ke darmiyan ana jana isi se hota hai. Ye is hisse ka sab se mashhoor sawal hai."),
      LessonBlock.example("Alt+F4 jo program samne khula hai use band kar deti hai. Desktop par dabao to shutdown wali screen ati hai. Upar F4 wale hisse me bhi ye baat ai thi, yahan phir dohra raha hun kyunke paper me ye sab se zyada ata hai."),
      LessonBlock.example("Windows+D seedha desktop dikha deti hai, tamam khuli windows neeche ho jati hain. D ko Desktop se jor kar yaad rakho."),
      LessonBlock.example("Windows+E File Explorer kholti hai, jahan tamam files aur folders milte hain. E ko Explorer se joro."),
      LessonBlock.example("Windows+L computer ko lock kar deti hai. Apni jagah se uthne se pehle ye dabana achi aadat bhi hai aur paper ka sawal bhi. L ko Lock se joro."),
      LessonBlock.example("Print Screen poori screen ki tasveer le leti hai, phir use Paint ya Word me Ctrl+V se chipkaya ja sakta hai. Laptop par ye key aksar PrtSc likhi hoti hai."),
      LessonBlock.example("Ctrl+Shift+Esc seedha Task Manager kholti hai. Jo program ruk jaye ya hang ho jaye, use yahin se band karte hain."),
      LessonBlock.example("Ctrl+Alt+Delete security wali screen lata hai, jahan se Task Manager, lock aur sign out ke options milte hain. Ye teeno keys aik sath dabti hain aur purane zamane se computer ko dobara chalane ka mashhoor tareeqa rahi hain. Farq yaad rakho. Task Manager seedha chahiye to Ctrl+Shift+Esc hai, aur bari security screen chahiye to Ctrl+Alt+Delete hai."),
      LessonBlock.heading("Aakhir me: paper ke sab se zyada dohraye jane wale 15 shortcuts"),
      LessonBlock.paragraph("Ab wo fehrist jo paper se aik raat pehle bhi parh lo to kaam ban jaye. Ye pandrah shortcuts one paper me ghum phir kar ate rehte hain."),
      LessonBlock.example("Ctrl+S file save karta hai."),
      LessonBlock.example("Ctrl+P print karta hai."),
      LessonBlock.example("Ctrl+C copy, Ctrl+X cut aur Ctrl+V paste karta hai."),
      LessonBlock.example("Ctrl+Z undo aur Ctrl+Y redo hai."),
      LessonBlock.example("Ctrl+A sab kuch select karta hai."),
      LessonBlock.example("Ctrl+B bold, Ctrl+I italic aur Ctrl+U underline hai."),
      LessonBlock.example("Ctrl+F find aur Ctrl+H replace hai."),
      LessonBlock.example("Ctrl+N nayi file aur Ctrl+O purani file kholta hai."),
      LessonBlock.example("F1 help ki key hai."),
      LessonBlock.example("F2 Excel me cell edit aur Windows me rename hai."),
      LessonBlock.example("F5 browser me refresh aur PowerPoint me slideshow hai."),
      LessonBlock.example("F7 spelling aur grammar check hai."),
      LessonBlock.example("F12 Save As kholti hai."),
      LessonBlock.example("Alt+Tab programs ke darmiyan switch hai aur Alt+F4 program band karti hai."),
      LessonBlock.example("Ctrl+Shift+Esc Task Manager kholti hai."),
      LessonBlock.paragraph("Aik aakhri baat zehen me rakho. Shortcut wale sawal me paper hamesha program ka naam de kar phasata hai. F5 ka jawab browser me aur hai aur PowerPoint me aur. Is liye sawal me pehle program ka naam dekho, phir key ka kaam batao. Ye aik aadat is pure hisse ke number pakke kar degi."),
    ],
  ),
  GeoTopic(
    id: "practical-word",
    title: "MS Word me Asal Kaam — Step by Step",
    subtitle: "Parhne ke sath sath haath se karna bhi seekho",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye lesson kyun zaroori hai"),
      LessonBlock.paragraph("Paper ke sawal rat lene se tum number to le loge, lekin jab asal zindagi me kisi daftar, school ya academy me computer ke samne bethna parega to wahan sawal nahi milega, kaam milega. Application likh do, CV bana do, result sheet tayyar kar do. Is lesson ka maqsad ye hai ke tum Word me ye saare kaam khud kar sako, baghair kisi se pooche. Main har kaam ko is tarah bata raha hun jese main tumhare paas betha hun aur tum meri ungli ke ishare par mouse chala rahe ho. Pehle ye dabao, phir ye khulega, yahan ye likho. Bas isi tartib par chalte jao, kaam khud hota jayega."),
      LessonBlock.paragraph("Aik mashwara shuru me hi de dun. Ye lesson sirf parhna mat. Agar computer paas hai to Word khol kar sath sath karte jao. Jo kaam aik dafa haath se ho jaye, wo zindagi bhar nahi bhoolta. Jo sirf parha jaye, wo paper wale din bhi dhundla ho jata hai."),
      LessonBlock.heading("Kaam 1: Application ya letter likhna"),
      LessonBlock.paragraph("Sab se pehle woh kaam seekho jo Pakistan me sab se zyada manga jata hai. School ke principal ko application, daftar me chhutti ki darkhwast, ya kisi idaray ko letter. Word kholte hi samne jo khaali safha ata hai, wahan se shuru karte hain."),
      LessonBlock.paragraph("Pehle safha set kar lo. Layout tab par jao. Wahan Size wale button se A4 chun lo, kyunke Pakistan me har daftar aur har photocopy wali dukaan A4 par chalti hai. Us ke sath Margins wale button se Normal chun lo, is se chaaron taraf aik inch ki jaga tayyar ho jati hai. Ye do kaam pehle karne ki wajah ye hai ke baad me page badalne se poori likhai hil jati hai. Pehle ghar ki buniyad, phir deewarein."),
      LessonBlock.paragraph("Ab likhna shuru karo. Sab se pehle upar bayen taraf se ye teen linein likho. Pehli line me To, likho. Dusri line me jis ko application de rahe ho us ka ohda aur idara likho, jese The Principal, Government High School, Lahore. Teesri line me sirf lafz Subject likh kar us ke aage apni darkhwast ki aik line wali wazahat likho, jese Subject: Application for leave. Subject wali line ko select karke Home tab se Bold kar do, taake parhne wale ko aik nazar me pata chal jaye ke darkhwast hai kis cheez ki."),
      LessonBlock.paragraph("Phir aik line chhor kar Respected Sir, ya Janab-e-Aala, likho. Phir asal body shuru hoti hai. Application ki body ke hamesha teen hisse hote hain, ye zehen me baitha lo. Pehle hisse me tum apna taaruf aur masla aik do jumlon me batate ho, jese main class 10 ka student hun aur mujhe bukhaar hai. Dusre hisse me tum apni asal guzarish likhte ho, jese meherbani karke mujhe do din ki chhutti di jaye. Teesre hisse me shukriya aur adab wala jumla ata hai, jese main aap ka shukarguzar rahunga. Bas, yahi teen hisse hain. Jo application in teen hisson me likhi ho wo kabhi nakaam nahi hoti."),
      LessonBlock.paragraph("Body ke baad aik line chhor kar Yours obediently, ya Aap ka farmanbardar, likho. Us ke neeche apna naam, phir class ya ohda, phir roll number ya mobile number jo munasib ho. Aik khaas baat. Apna naam hamesha body ke bilkul aakhir me ata hai, upar kabhi nahi. Upar sirf us ka naam hota hai jis ko application ja rahi hai."),
      LessonBlock.visual("Is hisse ki diagram me aik tayyar application ka safha dikhaya jaye, us par numbers lage hon — 1 page setup wali jagah, 2 To wali linein, 3 Subject wali line, 4 body ke teen hisse alag alag halke rangon me, 5 aakhir me naam wali jagah — taake student application ka poora dhancha aik nazar me dekh le."),
      LessonBlock.heading("Kaam 2: Formatting — likhai ko sajana"),
      LessonBlock.paragraph("Khali likh lena kaafi nahi hota. Jo document saaf aur saja hua ho, parhne wala usay sanjeedgi se leta hai. Ab wohi application jo tum ne likhi hai, use sajate hain."),
      LessonBlock.paragraph("Pehle heading ko bara aur mota karo. Heading wali line ko select karne ka sab se asaan tareeqa ye hai ke line ke aakhir par click karke mouse ghaseet-te hue poori line ko neele rang me rang lo, isay select karna kehte hain. Ab Home tab ke Font group me size wali khirki se 14 ya 16 chun lo, aur sath wale B wale button se Bold kar do. Dekho, heading khari ho gayi. Yahi kaam shortcut se bhi hota hai, select karke Ctrl+B dabane se text bold ho jata hai."),
      LessonBlock.paragraph("Font badalna ho to usi Font group me font wali bari khirki se apni pasand ka font chuno. Urdu mix documents me aksar log Times New Roman pasand karte hain kyunke wo sanjeeda lagta hai. Aam daftar ke kaam me Calibri bhi theek hai. Asal baat ye hai ke poore document me aik hi font rakho, har paragraph ka alag font document ko bazaar ka ishtehaar bana deta hai."),
      LessonBlock.paragraph("Alignment set karo. Heading ko beech me lane ke liye use select karke Home tab ke Paragraph group me Center wala button dabao, ya Ctrl+E dabao. Body ka text aam tor par bayen taraf seedha rehta hai, yani Left alignment, Ctrl+L. Agar tum chahte ho ke text akhbaar ke column ki tarah dono taraf se seedha ho jaye to Justify kar do, Ctrl+J. Application aur report me justify bohat saaf lagta hai."),
      LessonBlock.paragraph("Ab line spacing. Do lines ke darmiyan ka faasla. Body ke saare text ko select karo, is ke liye Ctrl+A dabao, poora document select ho jayega. Phir Home tab ke Paragraph group me Line Spacing wale button se 1.5 chun lo. Dekho, lines khul gayin aur parhna asaan ho gaya. Daftar ki applications me 1.5 spacing hi pasand ki jati hai kyunke parhne wale ko darmiyan me likhne ki jaga bhi mil jati hai."),
      LessonBlock.paragraph("Pehle paragraph ko indent karna seekho. Indent matlab paragraph ki pehli line baqi lines se thora andar se shuru ho. Paragraph ke shuru me click karo aur keyboard par Tab wali key aik dafa dabao. Pehli line andar khisak jayegi. Ye chhoti si cheez document ko parha likha banati hai."),
      LessonBlock.visual("Is hisse ki diagram me Home tab ka ribbon bara karke dikhaya jaye, Font group aur Paragraph group par ghaira ho, aur neeche aik hi paragraph chaar shaklon me dikhaya jaye — baghair formatting ke, bold heading ke sath, 1.5 spacing ke sath, aur indent ke sath — taake har tabdeeli ka asar ankh se nazar ajaye."),
      LessonBlock.heading("Kaam 3: CV ya Resume banana"),
      LessonBlock.paragraph("Ab woh kaam jo har naukri ke liye lazmi hai. CV woh kagaz hai jo tum se pehle daftar pohanchta hai, is liye ye sab se zyada mehnat wala kaam hai."),
      LessonBlock.paragraph("Nayi file kholo. Sab se upar apna naam sab se bare font me likho, size 20 ya 22, bold, center me. Us ke neeche chhote font me apna mobile number, email aur sheher likho. Yahi CV ka sarwaraq hai. Naam ke neeche wali line me apni degree ya pesha bhi likh sakte ho, jese B.A, Computer Operator."),
      LessonBlock.paragraph("Phir headings ki bari ati hai. CV me har hisse ki aik heading hoti hai aur tartib ye hoti hai. Pehle Objective, yani tum kya kaam dhund rahe ho, aik do lines me. Phir Education, yani taleem, sab se nayi degree sab se pehle. Phir Experience, yani kaam ka tajurba, agar hai to. Phir Skills, yani tumhe ata kya kya hai. Aur aakhir me Personal Information, yani walid ka naam, tareekh-e-paidaish, CNIC aur address."),
      LessonBlock.paragraph("Ab woh trick jo CV ko professional banati hai. Maloomat ko table me likho. Insert tab par jao, Table dabao aur do column wali table banao. Bayen column me labels likho, jese Name, Father Name, Date of Birth. Dayen column me un ke jawab likho. Table banane se har cheez seedhi line me rehti hai, kuch terha nahi hota. Phir table ki lines ghayab karni hain, kyunke CV me khanon wali lines achi nahi lagtin. Poora table select karo, upar Table Tools ke Design tab me Borders wale button se No Border chun lo. Lines gayab, lekin seedh aur tartib barkarar. Yahi professional CV ka raaz hai jo aksar logon ko nahi pata."),
      LessonBlock.paragraph("Education wale hisse me bhi table kaam ata hai. Wahan chaar column banao. Degree, Board ya University, Year, Marks ya Division. Har degree aik row me. Ye table lines ke sath hi rehne do, wahan lines achi lagti hain."),
      LessonBlock.paragraph("Aik aham mashwara. CV aik safhe ka ho to sab se behtar hai, do safhon se zyada kabhi na ho. Aur CV me jhoot kabhi mat likho, interview me pehla sawal CV se hi banta hai."),
      LessonBlock.visual("Is hisse ki diagram me aik mukammal tayyar CV ka safha dikhaya jaye, upar bara naam, neeche headings tartib se, aur aik hisse me woh table dikhayi jaye jis ki borders ghayab kar di gayi hon, sath teer se likha ho ke lines yahan se ghayab hoti hain."),
      LessonBlock.heading("Kaam 4: Table banana aur us me result likhna"),
      LessonBlock.paragraph("Table banana tum CV me seekh chuke ho, ab us ka dusra mashhoor istemal seekho. Class ka result."),
      LessonBlock.paragraph("Nayi file me pehle heading likho, Result Sheet Class 10, bold aur center. Phir Insert tab se Table dabao. Ab socho ke kitne column chahiye. Roll Number, Name, English, Urdu, Maths, Total. Ye che column hue. Aur rows kitni? Pehli row headings ke liye, us ke baad har student ki aik row. Agar paanch student hain to kul che rows. Table wale khane me mouse ghuma kar 6 guna 6 wala hissa select karo, click karte hi table safhe par ajayegi."),
      LessonBlock.paragraph("Ab pehli row me headings likho. Pehle cell me click karo, Roll likho, phir Tab key dabao, cursor agle cell me chala jayega. Isi tarah saari headings aur phir saara data bhar do. Table me age barhne ke liye Tab key hi istemal hoti hai, mouse se har cell par click karne ki zaroorat nahi. Aur aik maza ki baat, aakhri cell me Tab dabane se nayi row khud ban jati hai. To agar student barh jayen to ghabrana nahi."),
      LessonBlock.paragraph("Headings wali row ko select karke bold kar do. Agar table safhe se bahar nikal raha ho to column ki line ko mouse se pakar kar andar khisko, column tang ho jayega. Table ko rang dena ho to Table Tools ke Design tab me tayyar styles hote hain, aik click me poora table saj jata hai."),
      LessonBlock.visual("Is hisse ki diagram me aik bhari hui result wali table dikhayi jaye, pehli row bold ho, aur sath Insert tab me table select karne wala grid bhi chhota sa dikhaya jaye, taake student ko yaad rahe ke table kahan se ata hai."),
      LessonBlock.heading("Kaam 5: List, page number aur header"),
      LessonBlock.paragraph("Ab teen chhote lekin roz ke kaam aik sath seekho."),
      LessonBlock.paragraph("Pehla list banana. Farz karo tumhe zaroori kitabon ki list likhni hai. Har kitaab alag line par likho, saari linein select karo, phir Home tab ke Paragraph group me Bullets wala button dabao. Har line ke aage gola nishan ajayega. Agar number wali list chahiye, jese pehla dusra teesra, to us ke sath wala Numbering button dabao. Farq sirf itna hai ke bullets me tartib mayne nahi rakhti, numbering me rakhti hai. Dukaan ki khareedari ki list bullets me, kaam ke steps numbering me."),
      LessonBlock.paragraph("Dusra page number lagana. Insert tab par jao, Page Number wala button dabao. Wahan se chun lo ke number safhe ke upar chahiye ya neeche, aur neeche me bhi beech me ya kone me. Aam tor par neeche beech me lagta hai. Button dabate hi har safhe par number khud ajayega aur khud barhta jayega. Khud se har safhe par number type karna sab se bari bewaqoofi hai jo beginner karta hai, Word ye kaam khud karta hai."),
      LessonBlock.paragraph("Teesra header me apna naam lagana. Header safhe ke sab se upar wali woh jaga hai jahan likhi cheez har safhe par khud dohrai jati hai. Insert tab se Header dabao aur Blank chun lo. Ab jo khana khule wahan apna naam ya apne idaray ka naam likh do. Phir document ke beech me click kar do. Dekho, ab har safhe ke upar wohi naam ajayega. School ke notes aur lambay documents me ye bohat kaam ata hai. Neeche wali aisi hi jaga ko Footer kehte hain, page number aksar footer me hi lagta hai."),
      LessonBlock.visual("Is hisse ki diagram me aik safha dikhaya jaye jis ke upar header me naam likha ho, neeche footer me page number ho, aur beech me bullets wali list ho, teeno par number laga kar neeche naam likhe hon."),
      LessonBlock.heading("Kaam 6: Save karna, PDF banana aur print karna"),
      LessonBlock.paragraph("Kaam kar liya, ab use mehfooz karna aur duniya tak pohanchana seekho. Ye hisa sab se aham hai kyunke yahin sab se zyada nuqsan hota hai."),
      LessonBlock.paragraph("Save karna. File tab me Save dabao ya seedha Ctrl+S dabao. Pehli dafa save karne par window khulegi. Wahan do cheezain theek karni hain. Pehle jagah, yani file kahan save ho, Documents wala folder chun lo. Dusri naam, wahan Document1 mita kar apna saaf naam likho, jese Ahmed CV ya Leave Application November. Naam aisa rakho ke kal ko dhundne par foran mil jaye. Kaam ke darmiyan har paanch minute baad Ctrl+S dabane ki aadat dal lo. Bijli jane par wohi rota hai jis ne save nahi kiya hota."),
      LessonBlock.paragraph("PDF banana. Daftar wale aksar kehte hain PDF bhej do, kyunke PDF har mobile aur har computer par aik jaisi khulti hai aur us me tabdeeli bhi asaan nahi hoti. Tareeqa ye hai. File tab me jao, Save As dabao, phir jahan file ki type wali list hai wahan se PDF chun lo aur Save kar do. Tumhari file ki aik PDF copy ban jayegi. Asal Word wali file apni jagah mehfooz rahegi. CV hamesha PDF me bhejna chahiye taake agle ke computer par us ki shakal na bigde."),
      LessonBlock.paragraph("Print karna. File tab me Print dabao ya Ctrl+P dabao. Samne print wali screen ajayegi, dayen taraf safhe ki jhalak yani preview nazar ayega. Pehle preview gaur se dekho, jo ghalti screen par nazar ajaye wo kagaz par nahi hogi. Agar saare safhe chahiye to kuch karne ki zaroorat nahi. Agar sirf chand safhe chahiye to Pages wali khirki me likh do, jese 1-3 likhne se pehle teen safhe chhapenge, aur 2,5 likhne se sirf dusra aur paanchwa safha. Copies wali khirki me batao ke kitni copies chahiye. Phir Print wala bara button dabao. Aik aur baat, print karne se pehle printer me kagaz aur toner hai ya nahi, ye dekh lena aadhi preshani khatam kar deta hai."),
      LessonBlock.visual("Is hisse ki diagram me print wali screen dikhayi jaye, preview par ghaira ho, Pages wali khirki me 1-3 likha nazar aye, aur sath Save As wali list me PDF chuna hua dikhaya jaye."),
      LessonBlock.heading("Kaam 7: Spelling check chala kar document saaf karna"),
      LessonBlock.paragraph("Aakhri kaam, document ko bhejne se pehle us ki safai. Ghalat spelling wali application pehle hi minute me tumhari saakh gira deti hai."),
      LessonBlock.paragraph("Word tumhari madad khud karta hai. Jab tum koi lafz ghalat likhte ho to us ke neeche surkh rengti hui lakeer ajati hai. Us lafz par right click karo, Word tumhe sahi lafz ki peshkash karega, sahi wale par click kar do, lafz theek ho jayega. Neeli lakeer grammar ki ghalti par ati hai, wahan bhi right click se mashwara mil jata hai."),
      LessonBlock.paragraph("Poore document ki aik sath jaanch karni ho to keyboard se F7 dabao. Bayen taraf aik khana khul jayega jo aik aik karke har ghalti tumhare samne layega. Har ghalti par do raste honge. Agar Word ki peshkash sahi hai to us par click karke badal do. Aur agar lafz theek hai lekin Word use pehchanta nahi, jese Pakistani naamon ke sath aksar hota hai, to Ignore kar do, warna tumhara sahi naam bhi badal jayega. Ye bareeki khaas yaad rakho, spelling check andha saathi hai, faisla tum ne khud karna hai."),
      LessonBlock.paragraph("Saari ghaltiyan khatam hone par Word bata dega ke check mukammal ho gaya hai. Ab tumhara document bhejne ke qabil hai."),
      LessonBlock.visual("Is hisse ki diagram me aik jumla dikhaya jaye jis me aik lafz ke neeche surkh lakeer ho, us par right click wala menu khula ho aur sahi lafz par ghaira bana ho, sath F7 wali key bhi chhoti si dikhayi jaye."),
      LessonBlock.heading("Aam ghaltiyan jo beginner karta hai"),
      LessonBlock.paragraph("Ab wo ghaltiyan sun lo jo main har naye student ko karte dekhta hun, taake tum wo na karo."),
      LessonBlock.paragraph("Pehli ghalti, save na karna. Ghanton ka kaam aik bijli ke jhatke me gaya. Ctrl+S tumhari sab se achi aadat hai."),
      LessonBlock.paragraph("Dusri ghalti, har safhe par page number khud type karna. Phir jab beech me aik safha barhta hai to saare number ghalat ho jate hain. Page number hamesha Insert tab se lagao."),
      LessonBlock.paragraph("Teesri ghalti, khali jaga banane ke liye space bar ko das dafa dabana. Is se likhai terhi ho jati hai. Jaga set karni hai to Tab ya alignment istemal karo."),
      LessonBlock.paragraph("Chauthi ghalti, har paragraph ka alag font aur alag size rakhna. Document rang biranga ho jata hai aur parhne wala sanjeedgi se nahi leta. Aik font, do ya teen sizes, bas."),
      LessonBlock.paragraph("Paanchvi ghalti, spelling check ki har peshkash ko ankh band karke maan lena. Naam aur Urdu ke alfaaz wahan aksar ghalat kar diye jate hain. Ignore wala button isy liye bana hai."),
      LessonBlock.paragraph("Chhati ghalti, file ka naam Document1 hi rehne dena. Phir das files me se apni file dhundna azaab ban jata hai. Naam hamesha kaam ke hisaab se rakho."),
      LessonBlock.heading("Khud kar ke dekho"),
      LessonBlock.paragraph("Ab ye mashq khud karo, baghair kisi ki madad ke. Word kholo. Pehle aik application likho apne principal ko aik din ki chhutti ke liye, page A4 set karke, subject bold karke, body teen hisson me. Phir nayi file me apna CV banao, table ke sath, borders ghayab karke. Us ke baad usi CV wali file me neeche paanch kitabon ki bullets wali list banao. Phir file ko apne naam se save karo aur us ki PDF bhi banao. Aakhir me F7 chala kar saari spelling theek karo. Agar ye paanch kaam tum ne aik bethak me kar liye to samajh lo Word ki asal proficiency tumhare haath me agayi. Ab tum sirf paper ke sawal nahi, daftar ka kaam bhi kar sakte ho."),
    ],
  ),
  GeoTopic(
    id: "practical-excel",
    title: "MS Excel me Asal Kaam — Class ka Result Banana",
    subtitle: "Aik poori result sheet apne haath se banao",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye lesson kyun zaroori hai"),
      LessonBlock.paragraph("Excel ka naam sunte hi aksar student ghabra jata hai, kyunke use lagta hai ke ye sirf hisaab walon ka kaam hai. Asal me Excel har us shakhs ka kaam hai jise numberon ko tartib se rakhna hai. Aur is ka sab se mashhoor aur sab se zyada manga jane wala kaam hai class ka result banana. Har school, har academy, har coaching centre me result Excel me banta hai. Agar tum ye aik kaam seekh lo to samajh lo Excel ki aadhi proficiency tumhare haath me agayi."),
      LessonBlock.paragraph("Is lesson me hum khaali baatein nahi karenge. Hum asal me aik poori class ki result sheet banayenge, pehle khane se lekar print tak. Tum sath sath karte jao. Jahan formula ayega, wahan main pehle ye bataunga ke formula sochta kesay hai, phir likhne ka tareeqa. Kyunke formula ratne wale hamesha phanste hain, formula samajhne wale kabhi nahi phanste."),
      LessonBlock.heading("Qadam 1: Headings likhna"),
      LessonBlock.paragraph("Excel kholo. Samne khanon wali aik bari sheet hai. Yaad rakho, har khane ko cell kehte hain aur har cell ka aik naam hota hai jo us ke column wale harf aur row wale number se banta hai. Sab se upar bayen wala cell A1 hai. Usi par click karo aur pehli heading likho, Roll. Phir Tab key dabao, cursor B1 me chala jayega, wahan Name likho. Isi tarah age barhte jao. C1 me English, D1 me Urdu, E1 me Maths, F1 me Total, G1 me Percentage, H1 me Status. Tab dabate jao aur likhte jao, mouse ko haath lagane ki zaroorat hi nahi."),
      LessonBlock.paragraph("Ye tartib zehen me rakho. Pehle pehchan wali cheezain, Roll aur Name. Phir har mazmoon ke number. Phir un numberon se banne wali cheezain, Total, Percentage aur Status. Excel me hamesha yehi usool chalta hai, pehle asal data, phir us se nikli hui cheezain."),
      LessonBlock.visual("Is hisse ki diagram me Excel ki sheet ka upar wala hissa dikhaya jaye, pehli row me aath headings likhi nazar ayen, aur A1 cell par ghaira bana kar neeche likha ho ke cell ka naam column ke harf aur row ke number se banta hai."),
      LessonBlock.heading("Qadam 2: Data enter karna aur sheet ko saaf karna"),
      LessonBlock.paragraph("Ab dusri row se students ka data bharna shuru karo. A2 me pehla roll number likho, Enter dabao, cursor neeche ajayega, dusra roll number likho. Isi tarah pehle saare roll number bhar lo, phir B column me naam, phir C, D aur E me teeno mazameen ke number. Har mazmoon ke kul number 100 hain, ye baat aage percentage me kaam ayegi."),
      LessonBlock.paragraph("Data bharte hue aik preshani ayegi. Kisi student ka naam lamba hoga aur cell me pura nazar nahi ayega, aadha chhup jayega. Is ka hal ye hai ke column ko chora kar do. Column wale harf ke dayen kinare par mouse le jao, jab teer dono taraf wala ban jaye to double click kar do. Column khud apne sab se lambe naam ke barabar chora ho jayega. Isay AutoFit kehte hain. Teeno number wale column bhi isi tarah set kar lo."),
      LessonBlock.paragraph("Ab headings ko numayan karo. Pehli row ko select karo, is ke liye row wale number 1 par click karna kaafi hai, poori row select ho jayegi. Home tab se Bold wala button dabao. Phir usi Home tab me bucket yani rang wali balti wala button hota hai, Fill Color, us se halka sa rang, jese halka neela ya halka peela, pehli row me bhar do. Ab headings alag nazar ayengi aur sheet parhne wale ko foran samajh ayega ke upar wali line naam hain, neeche data hai. Chaho to poori sheet ka data select karke Borders wale button se All Borders laga do, har khane ke gird lakeer ajayegi aur sheet chhapi hui result jaisi lagne lagegi."),
      LessonBlock.visual("Is hisse ki diagram me bhari hui sheet dikhayi jaye, pehli row bold aur halke rang me ho, aik lambe naam wala column AutoFit se chora hua dikhaya jaye, aur column ke kinare par double click wali jagah par teer bana ho."),
      LessonBlock.heading("Qadam 3: Total ka formula — SUM"),
      LessonBlock.paragraph("Ab asal Excel shuru hota hai. Formula seekhne se pehle us ke peeche ki soch samajh lo. Formula Excel ko di gayi aik hidayat hai ke is khane me tum khud hisaab karke jawab rakho. Aur har formula hamesha barabar wale nishan se shuru hota hai, yani = se. Ye = hi Excel ko batata hai ke aage likhi cheez aam text nahi, hisaab hai. Agar tum = na lagao to Excel use sirf likhai samjhega aur koi hisaab nahi karega. Ye = wali baat Excel ki sab se buniyadi baat hai, isay kabhi na bhoolna."),
      LessonBlock.paragraph("Dusri baat, formula me hum number nahi likhte, cell ke naam likhte hain. Kyun? Kyunke agar kal ko kisi student ke number badal jayen to formula khud naya jawab nikaal lega. Agar tum ne formula me seedha number likh diye to number badalne par jawab purana hi rahega aur tumhe pata bhi nahi chalega. Cell ke naam wala formula zinda hota hai, number wala formula murda."),
      LessonBlock.paragraph("Ab amal karo. Pehle student ke Total wale cell me click karo, ye F2 hoga. Wahan ye likho =SUM(C2:E2) aur Enter dabao. Dekho, teeno mazameen ke number jud kar jawab ajayega. Is formula ko khol kar samjho. SUM ka matlab hai jama karo. C2:E2 ka matlab hai C2 se lekar E2 tak ke saare cell. Darmiyan wala colon, yani do nuqton wala nishan, Excel ki zubaan me se lekar tak ka matlab deta hai. To poora formula bola jaye to ye hai, C2 se E2 tak sab ko jama kar do."),
      LessonBlock.paragraph("Aik aur tareeqa bhi hai jo tumhe pata hona chahiye. Tum =C2+D2+E2 bhi likh sakte ho, jawab wohi ayega. Lekin jab mazameen teen ki jagah das hon to SUM wala tareeqa hi kaam ayega, das dafa jama ka nishan koi nahi lagata. Is liye SUM seekho."),
      LessonBlock.visual("Is hisse ki diagram me F2 cell select hua dikhaya jaye, upar formula bar me =SUM(C2:E2) likha nazar aye, aur C2 se E2 tak ke teen cell kisi rang se range hue hon, taake student ko dikhe ke formula kin khanon ko jama kar raha hai."),
      LessonBlock.heading("Qadam 4: Percentage ka formula"),
      LessonBlock.paragraph("Percentage ka concept pehle zehen me bithao. Percentage ka matlab hai har sau par kitna. Student ne teen mazameen me kul 300 me se number liye hain. Agar us ke kul 210 aye to us ki percentage wohi hogi jo 210 ko 300 se taqseem karke 100 se guna karne par ati hai, yani 70. Bas yahi hisaab formula me likhna hai."),
      LessonBlock.paragraph("G2 wale cell me click karo aur ye likho =F2/300 × 100 ke bajaye Excel ki zubaan me isay yun likhte hain =F2/300*100 lekin rukho, aik behtar aur saaf tareeqa hai. Sirf =F2/300 likho aur Enter dabao. Jawab 0.7 ajayega. Ghabrana nahi, hisaab sahi hai, bas shakal dusri hai. Ab isi cell ko select rakho aur Home tab ke Number group me % wala button dabado. Jawab foran 70% ban jayega. Asal me % wala button khud hi 100 se guna karke nishan laga deta hai. To usool ye bana, percentage ke liye kul ko kul numberon se taqseem karo, phir % wala button dabao. Agar % wala button na dabao to formula me khud *100 lagana parega, dono tareeqay sahi hain, pehla zyada saaf hai."),
      LessonBlock.paragraph("Yahan * wala nishan samajh lo. Keyboard par guna ka nishan × nahi hota, Excel me guna ke liye * istemal hota hai, taqseem ke liye / aur jama ke liye +, ghatane ke liye minus wala nishan. Ye chaar nishan Excel ke saare hisaab ki buniyad hain."),
      LessonBlock.visual("Is hisse ki diagram me G2 cell me 0.7 likha dikhaya jaye, phir usi cell ki dusri tasveer me % button dabane ke baad 70% nazar aye, darmiyan me Home tab ke % wale button par ghaira bana ho."),
      LessonBlock.heading("Qadam 5: Status ke liye IF ka formula"),
      LessonBlock.paragraph("Ab sab se zyada kaam ki cheez. Status wala column batayega ke student pass hai ya fail. Ye faisla Excel khud karega, tumhe har aik ko dekh kar nahi likhna parega. Is ke liye IF wala formula istemal hota hai. IF ka matlab hai agar. Ye formula Excel ko kehta hai ke agar ye shart sahi hai to ye likho, warna wo likho."),
      LessonBlock.paragraph("Is ke peeche ki soch ye hai. Hum Excel ko kahenge, agar is student ki percentage 40 ya us se zyada hai to PASS likho, warna FAIL likho. Bas, yahi jumla formula ki shakal me likhna hai."),
      LessonBlock.paragraph("H2 wale cell me click karo aur ye likho =IF(G2>=40,\"PASS\",\"FAIL\") aur Enter dabao. Jawab khud ajayega. Ab is formula ko tukron me khol kar samjho. IF ke baad bracket me pehli cheez shart hai, G2>=40, yani G2 ki qeemat 40 ke barabar ya us se bari hai. Ye >= wala nishan barabar ya zyada ka matlab deta hai. Shart ke baad pehla comma, phir \"PASS\", ye woh jawab hai jo shart sahi hone par ayega. Dusra comma, phir \"FAIL\", ye shart ghalat hone ka jawab hai. Aur aik bareeki, PASS aur FAIL ko double quotes me is liye likha hai kyunke ye alfaaz hain, number nahi. Excel me jo cheez lafzon me likhni ho use quotes me band karte hain, jo number ho use khula likhte hain. Ye farq na samjho to formula error de dega."),
      LessonBlock.paragraph("Ek baar ye formula chal jaye to tum ne Excel ka woh darwaza khol liya jahan computer tumhare liye faisle karta hai. Fees ki list me late wale, attendance me kam hazri wale, ye sab isi IF se pakre jate hain."),
      LessonBlock.visual("Is hisse ki diagram me H2 cell me PASS likha dikhaya jaye, upar formula bar me poora IF wala formula nazar aye, aur neeche formula ke teen hisse alag rangon me samjhaye gaye hon — shart, sahi wala jawab, ghalat wala jawab."),
      LessonBlock.heading("Qadam 6: Fill handle — formula sab par lagana"),
      LessonBlock.paragraph("Ab woh kaam jo asal proficiency hai. Tum ne formula sirf pehle student ke liye likha hai. Baqi bees students ke liye kya tum bees dafa formula likhoge? Bilkul nahi. Excel ne is ke liye fill handle diya hai."),
      LessonBlock.paragraph("F2 wale cell ko select karo. Us ke neeche dayen kone par aik bohat chhota sa kala chaukor khana nazar ayega. Yahi fill handle hai. Mouse ko us par le jao, imla nishan aik bare plus se badal kar patla kala plus ban jayega. Ab mouse daba kar neeche ki taraf ghaseeto, jitne students hain wahan tak, aur chhor do. Dekho, har student ka Total khud nikal aya."),
      LessonBlock.paragraph("Is ke peeche jo jadugari hai wo bhi samajh lo. Jab tum formula neeche ghaseette ho to Excel har row ke hisaab se cell ke naam khud badal deta hai. Dusri row me formula C3:E3 ka ban jayega, teesri me C4:E4 ka. Isay relative reference kehte hain, lekin naam ratne ki zaroorat nahi, bas ye samajh lo ke formula safar karta hai aur jahan jata hai wahan ke khanon ko pakar leta hai."),
      LessonBlock.paragraph("Yahi kaam G2 ke percentage wale aur H2 ke status wale formula par bhi karo. Teenon columns ko neeche tak bhar do. Chand seconds me poori class ka result tayyar. Aur aik tez tareeqa bhi bata dun, fill handle par double click kar do to formula khud wahan tak bhar jayega jahan tak sath wale column me data hai. Bees ho ya paanch sau students, waqt utna hi lagega."),
      LessonBlock.visual("Is hisse ki diagram me aik cell ke neeche dayen kone par bane chhote chaukor khane par bara ghaira bana ho, aur teer neeche ki taraf jata dikhaya jaye, sath teen rows me formula bharne ke baad ke jawabat nazar ayen."),
      LessonBlock.heading("Qadam 7: Class ki report — AVERAGE, MAX aur MIN"),
      LessonBlock.paragraph("Result ban gaya, ab teacher puchega ke class ki ausat percentage kya hai, sab se zyada number kis ke aye, sab se kam kis ke. Ye teeno jawab bhi formula dega."),
      LessonBlock.paragraph("Sheet ke neeche aik khaali jagah par likho Class Average. Us ke sath wale cell me ye formula likho =AVERAGE(G2:G21) aur Enter dabao. G2:G21 se murad hai doosri row se beesvi row tak ki saari percentages. Apni sheet me jitne students hain, aakhri row ka number wohi likhna. AVERAGE ka matlab hai ausat, saari percentages jud kar un ki tadaad par taqseem, lekin ye saara kaam Excel khud karega."),
      LessonBlock.paragraph("Isi tarah =MAX(F2:F21) likhne se sab se bara Total ajayega, aur =MIN(F2:F21) likhne se sab se chhota. MAX matlab sab se zyada, MIN matlab sab se kam. Ye teen formula mila kar tumhari sheet sirf result nahi rahi, report ban gayi. Principal ko class ki jo khulasa report chahiye hoti hai, wo yehi teen number hote hain."),
      LessonBlock.visual("Is hisse ki diagram me sheet ke neeche teen linein dikhayi jayen — Class Average, Highest, Lowest — aur har aik ke samne formula se aya hua jawab nazar aye, formula bar me AVERAGE wala formula dikhaya jaye."),
      LessonBlock.heading("Qadam 8: Sort karna aur filter lagana"),
      LessonBlock.paragraph("Ab do kaam jo result wale din sab se zyada hote hain."),
      LessonBlock.paragraph("Pehla sort karna. Merit list banani hai, yani sab se zyada number wala sab se upar. Apne data ke kisi bhi cell me click karo. Data tab par jao aur Sort wala button dabao. Aik window khulegi. Wahan Sort by wali list me Total chun lo, aur Order me Largest to Smallest chun lo, phir OK dabao. Poori sheet palat jayegi, pehle number wala sab se upar. Aik aham ehtiyat, sort karne se pehle hamesha file ko save kar lo, aur sort wali window me agar ye pucha jaye ke selection barhao to Expand the selection wala option chuno, warna sirf aik column paltega aur naam kisi ke aur number kisi ke ho jayenge. Ye ghalti bohat mehngi parti hai."),
      LessonBlock.paragraph("Dusra filter lagana. Maan lo tumhe sirf FAIL hue students ki list chahiye. Headings wali row select karo, Data tab se Filter wala button dabao. Har heading ke sath aik chhota sa teer ajayega. Status wale teer par click karo, wahan PASS ka tick hata kar sirf FAIL rakho, OK dabao. Ab sirf fail students nazar ayenge, baqi chhup jayenge, gaye nahi, sirf chhupe hain. Saari list wapas lane ke liye Filter wala button dobara dabado ya teer se Select All kar do. Filter chhoti list nikalne ke liye hai, sort tartib badalne ke liye hai, dono ka farq yaad rakho."),
      LessonBlock.visual("Is hisse ki diagram me do shaklein hon — aik me merit list bani hui sheet jahan sab se zyada total upar ho, dusri me filter ke baad sirf FAIL wale students nazar aa rahe hon aur Status wali heading par filter wala teer ghaira bana kar dikhaya jaye."),
      LessonBlock.heading("Qadam 9: Print ke liye tayyar karna"),
      LessonBlock.paragraph("Aakhri kaam, sheet ko kagaz par utarna. Excel ki sheet screen par jitni bhi saaf ho, print me aksar bigar jati hai kyunke ye kaam aksar log karte hi nahi."),
      LessonBlock.paragraph("Pehle Print Preview dekho, Ctrl+P dabao. Agar sheet do safhon me kat rahi hai to pehle orientation badlo. Page Layout tab par jao, Orientation se Landscape chun lo, sheet leti hui ho jayegi aur zyada column aik safhe me ajayenge. Phir bhi na aye to usi tab me Width wali setting ko 1 page kar do, Excel khud sheet ko thora chhota karke aik safhe me fit kar dega."),
      LessonBlock.paragraph("Agar data zyada hai aur sirf aik hissa print karna hai to woh hissa select karo, Page Layout tab se Print Area dabakar Set Print Area kar do. Ab sirf wohi hissa chhapega."),
      LessonBlock.paragraph("Aur sab se kaam ki setting, headings ko har safhe par dohrana. Agar result teen safhon ka hai to dusre safhe par headings nahi hongi aur parhne wala confuse hoga ke kaunsa column kis ka hai. Page Layout tab me Print Titles wala button dabao, Rows to repeat wali khirki me pehli row chun lo. Ab har safhe ke upar headings khud ajayengi. Print karne se pehle file save karna na bhoolna."),
      LessonBlock.visual("Is hisse ki diagram me print preview wali screen dikhayi jaye jahan landscape me poori sheet aik safhe par fit nazar aye, aur Page Layout tab ke Print Titles wale button par ghaira bana ho."),
      LessonBlock.heading("Aam ghaltiyan jo beginner karta hai"),
      LessonBlock.paragraph("Ab wo ghaltiyan jo main har naye Excel seekhne wale ko karte dekhta hun."),
      LessonBlock.paragraph("Pehli ghalti, formula se pehle = na lagana. Bina = ke Excel hisaab nahi karta, sirf text samajhta hai. Agar tumhara formula jawab ki jagah waisa ka waisa likha nazar aye to pehla shak isi = par karo."),
      LessonBlock.paragraph("Dusri ghalti, formula me cell ke naam ki jagah seedha number likh dena. Phir jab data badalta hai to jawab purana rehta hai aur ghalti pakri nahi jati."),
      LessonBlock.paragraph("Teesri ghalti, percentage me % wala button ya *100 bhool jana, phir 70 ki jagah 0.7 dekh kar ghabra jana. Hisab sahi hota hai, shakal adhuri hoti hai."),
      LessonBlock.paragraph("Chauthi ghalti, sort karte hue sirf aik column sort kar dena. Is se naam aur number ka rishta toot jata hai aur poora result kharab ho jata hai. Hamesha poora data select karke ya Expand the selection keh kar sort karo."),
      LessonBlock.paragraph("Paanchvi ghalti, filter laga kar samajhna ke baqi data khatam ho gaya. Filter sirf chhupata hai, mitata nahi. Filter hatate hi sab wapas ajata hai."),
      LessonBlock.paragraph("Chhati ghalti, file save na karna ya purani file par hi nayi file likh dena. Har term ke result ko alag naam se save karo, jese Result Class 10 December, taake purana record mehfooz rahe."),
      LessonBlock.heading("Khud kar ke dekho"),
      LessonBlock.paragraph("Ab ye mashq khud karo. Excel kholo aur das students ki result sheet banao, naam farzi rakh lo. Headings likho, data bharo, headings bold karke rang do. Phir SUM se Total, taqseem aur % wale button se Percentage, aur IF se Status nikalo. Teeno formula fill handle se neeche tak lagao. Phir AVERAGE se class ki ausat, MAX se sab se zyada aur MIN se sab se kam number nikalo. Us ke baad Total par sort karke merit list banao, phir filter laga kar sirf FAIL wale alag dikhao. Aakhir me sheet ko landscape karke, headings har safhe par dohrane ki setting laga kar print preview dekho. Agar ye sab tum ne aik bethak me kar liya to tum sirf Excel jante nahi ho, tum Excel me kaam kar sakte ho. Yahi asal proficiency hai."),
    ],
  ),
  GeoTopic(
    id: "practical-windows",
    title: "Windows aur PowerPoint ki Asal Proficiency",
    subtitle: "Roz ke kaam khud karna seekho",
    portion: "computer",
    blocks: <LessonBlock>[
      LessonBlock.heading("Ye lesson kyun zaroori hai"),
      LessonBlock.paragraph("Bohat se log computer ko saalon istemal karte hain lekin chhote chhote kaamon ke liye dusron ke mohtaj rehte hain. File idhar se udhar karni hai, kisi ko bulao. Screenshot lena hai, mobile se photo kheench lo. Program hang ho gaya, computer band kar do. Ye proficiency nahi hai. Proficiency ye hai ke roz ke ye saare kaam tum khud, sakoon se, baghair ghabraye kar lo."),
      LessonBlock.paragraph("Is lesson ke do hisse hain. Pehle hisse me Windows ke woh kaam seekhenge jo har roz parte hain. Dusre hisse me PowerPoint me asal presentation banana seekhenge, sirf ye nahi ke slides kesay banti hain, balkay ye bhi ke achhi presentation hoti kesay hai. Dono hisse step by step hain, sath sath karte jao."),
      LessonBlock.heading("Pehla hissa: Windows ke roz ke kaam"),
      LessonBlock.heading("Kaam 1: File aur folder banana, naam badalna"),
      LessonBlock.paragraph("Folder woh almari hai jis me tum apni files tartib se rakhte ho. Desktop par ya kisi drive me khaali jagah par right click karo. Jo menu khule us me New par jao, phir Folder par click karo. Aik naya folder ban jayega aur us ka naam neele rang me likhne ke liye tayyar hoga. Wahan apna naam likho, jese Meri Documents, aur Enter dabao. Bas, folder tayyar."),
      LessonBlock.paragraph("File banana bhi isi menu se hota hai. Right click, New, aur phir jo file chahiye wo chun lo, jese Text Document ya Word Document. File ban jayegi, naam likh kar Enter dabado."),
      LessonBlock.paragraph("Naam badalna yani rename karna is se bhi asaan hai. File ya folder ko aik dafa click karke select karo, phir keyboard par F2 dabao. Naam likhne ke liye tayyar ho jayega, naya naam likho aur Enter dabao. F2 wali key yaad rakh lo, ye rename ki fix key hai aur paper me bhi ati hai. Aik bareeki, file ka naam badalte waqt us ke aakhir wali extension, jese .docx ya .jpg, ko hath na lagana. Wo badal di to file khulna band ho jayegi, kyunke Windows extension se pehchanta hai ke file kis program ki hai."),
      LessonBlock.visual("Is hisse ki diagram me desktop par right click wala menu khula dikhaya jaye, New aur phir Folder par ghaira bana ho, aur sath F2 wali key chhoti si dikhayi jaye."),
      LessonBlock.heading("Kaam 2: Copy paste aur cut paste ka farq"),
      LessonBlock.paragraph("Ye do kaam dekhne me aik jese hain lekin in ka farq na samajhna bohat mehnga parta hai, is liye amal se samjho."),
      LessonBlock.paragraph("Copy paste ka matlab hai file ki aik naqal dusri jagah banana. Asal file apni jagah rehti hai, dusri jagah us ki copy ajati hai. Tareeqa ye hai. File ko select karo, Ctrl+C dabao. Ab jahan file chahiye wahan jao, us folder ko kholo aur Ctrl+V dabao. File ajayegi. Peeche murr kar dekho, asal file pehli jagah par bhi mojood hai. Ab file do jagah hai."),
      LessonBlock.paragraph("Cut paste ka matlab hai file ko uthha kar le jana. File ko select karo, Ctrl+X dabao. Dusri jagah ja kar Ctrl+V dabao. File ajayegi, lekin pehli jagah se gayab ho jayegi. Ab file sirf aik jagah hai."),
      LessonBlock.paragraph("Farq aik jumle me yaad kar lo. Copy me file do jagah hoti hai, cut me file jagah badalti hai. Jab file ki naqal rakhni ho, jese USB me backup lena, to copy karo. Jab file ko tartib se dusre folder me muntaqil karna ho to cut karo. Aur aik aham ehtiyat, cut karne ke baad jab tak paste na kar do, computer band na karna aur dusra cut ya copy na karna, warna file darmiyan me atak sakti hai. Paste karte hi kaam mukammal ho jata hai."),
      LessonBlock.paragraph("Yehi kaam mouse se bhi hota hai. File par right click karne se Copy aur Cut dono options mil jate hain, aur dusri jagah right click karne se Paste mil jata hai. Keys tez hain, mouse asaan hai, dono seekh lo."),
      LessonBlock.visual("Is hisse ki diagram me do shaklein hon — pehli me aik file copy hokar do folders me nazar aye, dusri me wohi file cut hokar pehle folder se gayab aur dusre me mojood ho, aur neeche Ctrl+C, Ctrl+X aur Ctrl+V ki keys dikhayi jayen."),
      LessonBlock.heading("Kaam 3: Delete karna aur Recycle Bin se wapas lana"),
      LessonBlock.paragraph("Jo file nahi chahiye use select karke keyboard par Delete wali key dabao. File gayab ho jayegi. Lekin aik sukoon ki baat sun lo, Delete dabane se file hamesha ke liye khatam nahi hoti. Wo Recycle Bin me jati hai, jo desktop par kachre wali tokri ke nishan se bana hota hai. Ye Windows ki hifazati jaali hai."),
      LessonBlock.paragraph("Galti se delete ho jaye to ghabrana nahi. Desktop par Recycle Bin kholo. Saari delete shuda files wahan milengi. Apni file par right click karo aur Restore dabao. File apni asal jagah par wapas ajayegi, jahan se delete hui thi bilkul wahan. Aur agar tum chahte ho ke Recycle Bin ki saari files hamesha ke liye khatam ho jayen to Recycle Bin par right click karke Empty Recycle Bin kar do. Us ke baad wapas lana mumkin nahi rehta, is liye ye button soch kar dabana."),
      LessonBlock.paragraph("Aik aur bareeki bata dun. Agar tum file ko select karke Shift ke sath Delete dabao to file Recycle Bin me nahi jayegi, seedha hamesha ke liye khatam ho jayegi. Ye shortcut taqatwar hai aur khatarnak bhi. Jab tak pakka yakeen na ho, istemal na karna."),
      LessonBlock.visual("Is hisse ki diagram me Recycle Bin khula dikhaya jaye, us me delete shuda files nazar ayen, aik file par right click wala menu khula ho aur Restore par ghaira bana ho."),
      LessonBlock.heading("Kaam 4: Screenshot lena"),
      LessonBlock.paragraph("Screenshot matlab screen par jo kuch nazar aa raha hai us ki tasveer. Ye bohat kaam ki cheez hai. Koi error aye to us ka screenshot bhej kar koi bhi tumhari madad kar sakta hai. Koi online payment ki raseed ho to screenshot saboot ban jata hai."),
      LessonBlock.paragraph("Sab se purana aur asaan tareeqa Print Screen wali key hai. Keyboard par upar wali line me PrtSc likhi key hoti hai. Use aik dafa dabao, poori screen ki tasveer memory me copy ho jayegi, lekin tumhe nazar kuch nahi ayega. Ab Paint ya Word kholo aur Ctrl+V dabao, tasveer ajayegi. Phir use save kar lo. Agar sirf mojooda window ki tasveer chahiye, poori screen ki nahi, to Alt ke sath Print Screen dabao."),
      LessonBlock.paragraph("Dusra aur behtar tareeqa Snipping Tool hai. Start menu me Snipping Tool likh kar dhundo aur kholo. New wala button dabao, screen halki si dhundli ho jayegi. Ab mouse se wo hissa ghaseet kar select karo jis ki tasveer chahiye. Chhorte hi woh hissa kat kar ajayega. Save wala button daba kar use naam de kar save kar lo. Snipping Tool ka faida ye hai ke tum sirf zaroori hissa lete ho, poori screen ki bheer nahi. Aaj kal ke Windows me Windows key ke sath Shift aur S dabane se bhi yehi kaam foran ho jata hai, ye shortcut khaas yaad rakhne wala hai."),
      LessonBlock.visual("Is hisse ki diagram me Snipping Tool khula dikhaya jaye, screen ke aik hisse ke gird ghaseeta hua khana bana nazar aye, aur neeche Print Screen aur Windows+Shift+S ki keys likhi hon."),
      LessonBlock.heading("Kaam 5: File ko zip karna aur kholna"),
      LessonBlock.paragraph("Zip karna matlab files ko dabaa kar aik chhote packet me band karna. Is ke do faide hain. Aik, kai files aik file ban jati hain, bhejna asaan ho jata hai. Dusra, size kam ho jata hai. Email me kai files bhejni hon to zip bana kar bhejna hi aqalmandi hai."),
      LessonBlock.paragraph("Tareeqa ye hai. Jin files ko zip karna hai un sab ko select karo. Aik se zyada files select karne ke liye pehli file par click karo, phir Ctrl dabaye rakh kar baqi files par aik aik karke click karte jao. Sab select ho jayen to kisi aik par right click karo. Menu me Send to par jao, phir Compressed zipped folder par click karo. Wahi aik zip file ban jayegi. Us ka naam F2 se apni marzi ka rakh lo. Bas, packet tayyar hai."),
      LessonBlock.paragraph("Zip kholna is se bhi asaan hai. Zip file par right click karo aur Extract All dabao. Aik window khulegi jo puchegi ke files kahan nikaalun, jagah chun kar Extract dabado. Saari files nikal kar aik folder me ajayengi. Aik baat yaad rakho, zip ke andar wali file ko seedha khol kar kaam na karo, pehle extract karo, warna tumhari tabdeeli save nahi hogi aur tum samjhoge ke kaam ho gaya hai."),
      LessonBlock.visual("Is hisse ki diagram me right click wala menu dikhaya jaye jis me Send to ke neeche Compressed zipped folder par ghaira bana ho, aur sath aik zip file ka icon bhi dikhaya jaye jis par bandh wali patti bani hoti hai."),
      LessonBlock.heading("Kaam 6: USB lagana aur safely nikalna"),
      LessonBlock.paragraph("USB lagana to sab ko ata hai, lekin use nikalna aksar log ghalat karte hain aur phir kehte hain ke data kharab ho gaya."),
      LessonBlock.paragraph("USB lagate hi screen par aik paighaam ata hai aur USB aik nayi drive ki shakal me This PC me nazar ane lagti hai. Files copy karna ho to bilkul wese hi karo jese pehle seekha, copy aur paste."),
      LessonBlock.paragraph("Asal kaam nikalne ka hai. Jab kaam khatam ho jaye to USB ko kheench kar na nikalo. Screen ke neeche dayen kone me, ghari ke paas, aik chhota sa teer hota hai, use dabao to chhupe hue nishan khul jate hain. Un me USB wala nishan milega, us par click karo aur Eject wala option dabao. Jab paighaam aye ke ab nikalna mehfooz hai, tab USB nikalo. Is ki wajah ye hai ke kabhi kabhi Windows peeche file par kaam kar raha hota hai, aur achanak nikalne se wo file aadhi reh jati hai aur kharab ho jati hai. Das second ka ye kaam tumhare mehnat ke data ko bachata hai."),
      LessonBlock.visual("Is hisse ki diagram me screen ka neeche dayen wala kona bara karke dikhaya jaye, USB wala nishan aur Eject wala option ghaira bana kar dikhaya jaye, aur sath woh paighaam bhi ho ke ab hardware nikalna mehfooz hai."),
      LessonBlock.heading("Kaam 7: Program install aur uninstall karna"),
      LessonBlock.paragraph("Naya program lagana yani install karna. Program ki setup wali file, jo aam tor par .exe hoti hai, use double click karo. Aik window khulegi, Next dabate jao, shartein ayen to I Agree ya Accept karo, aur aakhir me Install dabado. Kuch dair me program Start menu me ajayega. Aik ehtiyat, program hamesha us ki asal website ya bharose wali jagah se lo. Har chamakti hui website se download karna virus ko dawat dena hai, aur download ke waqt jo fazool izafi programs lagne ki peshkash ho, un ke tick hata dena."),
      LessonBlock.paragraph("Program hatana yani uninstall karna bhi ana chahiye, warna computer fazool cheezon se bhar jata hai. Settings kholo, Apps me jao. Saare programs ki list ajayegi. Jo program hatana hai use chun kar Uninstall dabao, phir us ki window me Next ya Uninstall dabate jao. Program saaf ho jayega. Program ko us ke folder ko delete karke kabhi na hatao, is se us ki aadhi files computer me reh jati hain aur jaga bhi gherti hain aur maslay bhi banati hain. Sahi tareeqa hamesha Settings se uninstall hai."),
      LessonBlock.visual("Is hisse ki diagram me Settings ke Apps wale hisse ki list dikhayi jaye, aik program par Uninstall wala button ghaira bana kar dikhaya jaye."),
      LessonBlock.heading("Kaam 8: Task Manager se hang program band karna"),
      LessonBlock.paragraph("Kabhi kabhi koi program atak jata hai. Mouse ghumta rehta hai, click ka jawab nahi ata, screen par Not Responding likha ajata hai. Aise me aksar log seedha computer ka button daba kar band kar dete hain, jis se khuli files ka data zaya ho jata hai. Sahi tareeqa Task Manager hai."),
      LessonBlock.paragraph("Keyboard se Ctrl+Shift+Esc dabao. Task Manager khul jayega, jis me chal rahe saare programs ki list hoti hai. Atke hue program ke samne aksar Not Responding likha hota hai. Use select karo aur neeche ya upar End Task wala button dabado. Sirf wohi program band hoga, baqi computer bilkul theek chal raha hoga, aur tumhari dusri files mehfooz rahengi. Phir us program ko dobara khol lo, aksar dobara khulne par woh theek chal parta hai."),
      LessonBlock.paragraph("Aik aur tareeqa bhi hai, Ctrl+Alt+Delete dabane se aik screen ati hai jahan se bhi Task Manager khulta hai. Lekin Ctrl+Shift+Esc seedha aur tez hai. Ye shortcut apne paas likh kar rakh lo, ye har us din kaam ayega jab computer atak jayega."),
      LessonBlock.visual("Is hisse ki diagram me Task Manager ki window dikhayi jaye, aik program ke samne Not Responding likha nazar aye, aur End Task wale button par ghaira bana ho, sath Ctrl+Shift+Esc ki keys bhi dikhayi jayen."),
      LessonBlock.heading("Dusra hissa: PowerPoint me asal presentation banana"),
      LessonBlock.paragraph("Ab presentation seekho. PowerPoint woh app hai jis me tum apni baat bare parde par, slides ki shakal me pesh karte ho. Class me topic samjhana ho, daftar me report deni ho, yehi app kaam ati hai."),
      LessonBlock.heading("Qadam 1: Pehli title slide banana"),
      LessonBlock.paragraph("PowerPoint kholo aur Blank Presentation chun lo. Samne pehli slide ajayegi jis me do khane honge. Upar wale bare khane me apni presentation ka naam likho, jese Pani ki Ahmiyat. Neeche wale chhote khane me apna naam aur class ya ohda likho. Ye title slide hai, ye tumhari presentation ka chehra hai. Is par font bara rakho, taake kamre ke aakhir me bethe shakhs ko bhi parhna ajaye. Agar tayyar design chahiye to Design tab se koi theme chun lo, poori presentation ka rang aur andaaz aik sath badal jayega. Theme shuru me lagana asaan hota hai, baad me lagane se bhi ho jata hai lekin pehle wala sakoon nahi rehta."),
      LessonBlock.heading("Qadam 2: Nayi slides lagana"),
      LessonBlock.paragraph("Ab har topic ke liye alag slide banao. Nayi slide lane ki key Ctrl+M hai, ye yaad kar lo. Ya Home tab se New Slide wala button dabao. Nayi slide aye to us ki shakal bhi soch kar chuno. New Slide ke neeche wale teer se layout milte hain. Jahan sirf heading aur points chahiye wahan Title and Content wala layout lo. Jahan do cheezon ka muqabla karna hai wahan Two Content wala lo, aik taraf aik cheez, dusri taraf dusri. Slide ke bare khane me apna heading likho aur neeche wale khane me apne points likho. Har point alag line par, Enter dabate hi naya point khud ban jayega."),
      LessonBlock.paragraph("Aik presentation ka dhancha ye rakho. Pehli slide naam wali. Dusri slide aaj ke topics ki list. Phir har topic ki aik ya do slides. Aur aakhir me aik slide shukriya ya sawalat wali. Yahi tartib har achhi presentation ki hoti hai."),
      LessonBlock.visual("Is hisse ki diagram me PowerPoint ki window dikhayi jaye, bayen taraf slides ki chhoti chhoti shaklein tartib se lagi hon, beech me title slide khuli ho, aur Ctrl+M ki keys neeche likhi hon."),
      LessonBlock.heading("Qadam 3: Animation lagana — cheezain aik aik karke lana"),
      LessonBlock.paragraph("Animation ka matlab hai slide ke andar wali cheez ko harkat de kar lana. Is ka asal faida ye hai ke tum apne points aik aik karke screen par la sakte ho. Agar saare points aik sath ajayen to sunne wale pehle hi sab parh lete hain aur tumhari baat sunna chhor dete hain. Aik aik karke lane se un ki tawajjo tumhare sath chalti hai."),
      LessonBlock.paragraph("Tareeqa ye hai. Jis text wale khane ko animate karna hai use select karo. Animations tab par jao. Wahan shuru me hare rang ke sitaron wale options hote hain, ye screen par lane wale effects hain. Un me se Fade ya Appear jesa saada sa effect chun lo. Bas, lag gaya. Ab slideshow me jab tum click karoge to points aik aik karke ayenge. Agar tum chahte ho ke points bilkul aik aik karke ayen, aik click par aik point, to animation wale khane me By Paragraph wala option rehne do, aam tor par wo pehle se set hota hai."),
      LessonBlock.paragraph("Aik mashwara, animation saada rakho. Har cheez ko ghuma kar, uchhaal kar, teer ki tarah lana presentation ko circus bana deta hai aur asal baat kahin kho jati hai. Professional log aik hi saada effect poori presentation me rakhte hain."),
      LessonBlock.heading("Qadam 4: Transition lagana — slide badalne ka andaaz"),
      LessonBlock.paragraph("Transition animation se alag cheez hai, ye farq pakka kar lo. Animation slide ke andar ki cheez par lagta hai. Transition slide ke badalne par lagta hai, yani jab aik slide ja kar dusri ati hai to darmiyan me jo andaaz banta hai wo transition hai."),
      LessonBlock.paragraph("Tareeqa ye hai. Bayen taraf se woh slide chun lo jis par transition lagana hai. Transitions tab par jao. Wahan Fade, Push, Morph jese options milenge. Aik chun lo. Agar yehi transition saari slides par lagana hai to Apply To All wala button dabado, har slide par wohi lag jayega. Yehi sahi tareeqa hai, har slide ka alag transition presentation ko be-tartib kar deta hai. Aik hi saada transition, jese Fade, poori presentation ke liye kaafi hai."),
      LessonBlock.visual("Is hisse ki diagram me do hisse hon — aik me Animations tab khula ho aur aik text wale khane par effect laga dikhaya jaye, dusre me Transitions tab khula ho aur Apply To All par ghaira bana ho, neeche aik line me dono ka farq likha ho ke animation andar ki cheez par, transition slide badalne par."),
      LessonBlock.heading("Qadam 5: Slideshow chala kar dekhna"),
      LessonBlock.paragraph("Presentation ban gayi, ab use chala kar dekho, bilkul wese jese asal me pesh karoge. Keyboard se F5 dabao. Poori screen par pehli slide ajayegi. Age barhne ke liye mouse click karo, ya space wali key dabao, ya teer wali key. Peeche jana ho to bayen wala teer. Darmiyan me khatam karna ho to Esc dabao, tum wapas apni window me ajayoge. Agar tum chahte ho ke show mojooda slide se shuru ho, pehli se nahi, to Shift ke sath F5 dabao."),
      LessonBlock.paragraph("Slideshow chalate hue aik cheez khaas dekho. Koi slide par text to zyada nahi ho gaya, koi lafz kinare se kat to nahi raha, rang parhne me aa to raha hai. Jo ghalti tumhe ab nazar ajaye wo use abhi theek kar lo, pesh karte waqt saamne walon ko nazar ayegi aur wahan theek karne ka mauqa nahi hoga. Apni presentation ko aik dafa khud sunne wale ban kar dekhna hi asal proficiency hai."),
      LessonBlock.heading("Achhi presentation ke usool"),
      LessonBlock.paragraph("Ab wo usool jo tumhe aam student se alag karenge. Ye kisi button me nahi milte, ye samajh me milte hain."),
      LessonBlock.paragraph("Pehla usool, aik slide par kam text. Slide tumhari parchi nahi hai, wo sunne walon ke liye ishara hai. Agar tum ne poora paragraph slide par likh diya to log parhte rahenge, tumhe koi nahi sunega. Slide par sirf bare points likho, tafseel tum apni zubaan se batao. Aik slide par paanch che points se zyada na hon."),
      LessonBlock.paragraph("Dusra usool, font bara rakho. Heading kam az kam 32 ya 36 ki, aur points kam az kam 24 ke. Jo lafz kamre ke aakhir se na parha jaye, wo slide par hone ka koi faida nahi."),
      LessonBlock.paragraph("Teesra usool, har cheez tasveer se samjhane ki koshish na karo. Jahan process ya tartib samjhani ho wahan diagram ya saada sa chart zyada kaam karta hai. Aur tasveer wohi lagao jo baat se milti ho, sirf sajawat ke liye lagi tasveer tawajjo bant deti hai."),
      LessonBlock.paragraph("Chautha usool, rangon ka shor na karo. Aik theme, do ya teen rang, bas. Har slide ka alag rang aur har line ka alag font presentation ko na-parha likha bana deta hai."),
      LessonBlock.paragraph("Paanchva usool, pehle se mashq. Presentation dene se pehle aik dafa akelay me bol kar dekho. Waqt bhi pata chal jayega aur atakne wali jagahen bhi. Jo shakhs mashq karke jata hai, wo stage par kabhi nahi ghabrata."),
      LessonBlock.visual("Is hisse ki diagram me do slides sath sath dikhayi jayen — aik me chhota font aur paragraph bharay hue hon aur us par ghalat ka nishan ho, dusri me bare points aur bara font ho aur us par sahi ka nishan ho, taake farq ankh se zehen me baith jaye."),
      LessonBlock.heading("Aam ghaltiyan jo beginner karta hai"),
      LessonBlock.paragraph("Ab wo ghaltiyan jo main roz dekhta hun, taake tum na karo."),
      LessonBlock.paragraph("Pehli ghalti, USB kheench kar nikaal lena. Data kharab hone ki sab se aam wajah yehi hai. Hamesha Eject karke nikalo."),
      LessonBlock.paragraph("Dusri ghalti, file ka naam badalte hue extension mita dena. Us ke baad file kisi program me nahi khulti aur log samajhte hain ke file kharab ho gayi."),
      LessonBlock.paragraph("Teesri ghalti, program hang hone par seedha computer band kar dena. Pehle Task Manager se sirf wohi program band karo, baqi kaam bach jayega."),
      LessonBlock.paragraph("Chauthi ghalti, zip ke andar hi file khol kar kaam karna aur phir tabdeeli ka gayab ho jana. Hamesha pehle extract karo."),
      LessonBlock.paragraph("Paanchvi ghalti, presentation ki har slide par paragraph bhar dena aur chhota font rakhna. Sunne wale parh bhi nahi sakte aur sun bhi nahi sakte."),
      LessonBlock.paragraph("Chhati ghalti, har slide par alag animation aur alag transition lagana. Presentation maloomat ki jagah tamasha ban jati hai. Saadgi hi professional pehchan hai."),
      LessonBlock.heading("Khud kar ke dekho"),
      LessonBlock.paragraph("Ab ye mashq khud karo, dono hisso ki. Pehle Windows wali. Desktop par apne naam ka folder banao, us ke andar aik text file banao aur us ka naam F2 se badal kar Meri File rakho. Phir us file ko copy karke dusre folder me rakho, aur asal wali ko cut karke pehle folder se hata kar dekho ke copy aur cut ka farq ankh se nazar aye. Phir koi file delete karke Recycle Bin se restore karo. Apni screen ka aik screenshot Snipping Tool se lo aur save karo. Apni do files ko zip banao aur phir extract karke dekho. Aur Task Manager khol kar dekho ke is waqt kaun kaun se program chal rahe hain, band koi na karna, sirf pehchano."),
      LessonBlock.paragraph("Phir PowerPoint wali mashq. Apne pasandida topic par paanch slides ki presentation banao. Pehli title slide, dusri topics ki list, do slides asal maloomat ki, aakhri sawalat wali. Aik theme lagao, points par saada animation lagao, saari slides par aik hi transition lagao. Phir F5 daba kar poora show chalao aur sunne wale ki nazar se dekho. Agar dono mashqain tum ne kar lin to samajh lo ke computer tumhare liye ajnabi nahi raha, tum us ke asal malik ban gaye ho. Yahi woh proficiency hai jo paper se bahar ki zindagi me kaam ati hai."),
    ],
  ),
];
